local ns = select(2, ...)

ns.Locale("esES", function(L)
	L["binding.birch.description"] = "Pálida y como de papel, con motas oscuras. Seguramente el único libro de aquí que flotaría."
	L["binding.birch.name"] = "Corteza de abedul"
	L["binding.bone.description"] = "Cuero crudo tensado sobre un bastidor y cerrado con dos pasadores de hueso tallado. Cruje con el frío."
	L["binding.bone.name"] = "Hueso y cuero crudo"
	L["binding.brasscase.description"] = "Un estuche de latón grabado con un pez saltando sobre los juncos, y un cierre que hace clic como si fuera en serio."
	L["binding.brasscase.name"] = "Estuche de latón de cazador"
	L["binding.buckram.description"] = "Tela rígida verde mar con filetes crema. La espuma se queda en gotas y resbala sin más."
	L["binding.buckram.name"] = "Bucarán verde mar"
	L["binding.canvas.description"] = "Lona caqui sencilla, estarcida con un número que nadie recuerda haber asignado. Cabe en el bolsillo de un abrigo, justo."
	L["binding.canvas.name"] = "Libreta de lona"
	L["binding.chartlinen.description"] = "Lino pálido estampado con una carta antigua, las líneas de profundidad gastadas en las esquinas tras unas cuantas temporadas de pulgares."
	L["binding.chartlinen.name"] = "Lino de carta de mareas"
	L["binding.copper.description"] = "Placas de cobre remachadas sobre tablas, verdes en las juntas. Ruidoso al cerrar, imposible de abollar."
	L["binding.copper.name"] = "Cobre remachado"
	L["binding.coral.description"] = "Ramas de coral rojo engastadas en cuero verde mar, con perlas donde terminan las ramas."
	L["binding.coral.name"] = "Incrustación de coral"
	L["binding.driftwood.description"] = "Tres tablas de madera gris de deriva, clavadas a un lomo de cuero. Pesado, honrado y un poco salado."
	L["binding.driftwood.name"] = "Tapas de madera flotante"
	L["binding.eelskin.description"] = "Tiras de piel de anguila cosidas una junto a otra, oscuras y resbaladizas, con un brillo que se mueve cuando se mueve la luz."
	L["binding.eelskin.name"] = "Piel de anguila"
	L["binding.field.description"] = "Cuero marrón sencillo, hecho para mojarse con la lluvia, y suele mojarse."
	L["binding.field.name"] = "Cuero de campo"
	L["binding.frosthide.description"] = "Piel curada en el frío hasta volverse blanca, ribeteada de pelo en el lomo para manos sin guantes."
	L["binding.frosthide.name"] = "Piel curtida en hielo"
	L["binding.kodo.description"] = "Una piel gruesa de las llanuras, pelada a trozos y cerrada con cordones de cuero crudo. Durará más que el pescador."
	L["binding.kodo.name"] = "Piel de kodo"
	L["binding.kraft.description"] = "Papel de estraza frotado con cera de abeja hasta que la lluvia le resbala. Atado con bramante, porque los botones se caen."
	L["binding.kraft.name"] = "Papel kraft encerado"
	L["binding.lacquer.description"] = "Capa sobre capa de laca roja, pulida hasta reflejar, con una carpa dorada nadando dentro."
	L["binding.lacquer.name"] = "Laca roja"
	L["binding.maplinen.description"] = "Un mapa a mano sobre lino, con la senda punteada en rojo y una X donde alguien jura que vive el grande."
	L["binding.maplinen.name"] = "Lino con mapa"
	L["binding.morocco.description"] = "Piel de cabra roja repujada entera con una celosía de oro, de esas encuadernaciones que suelen guardarse tras un cristal."
	L["binding.morocco.name"] = "Tafilete dorado"
	L["binding.moss.description"] = "Cuero que pasó demasiado tiempo en una orilla húmeda. El musgo prendió, y el libro parece más contento así."
	L["binding.moss.name"] = "Musgoso"
	L["binding.netcork.description"] = "Tapas de corcho bajo una red anudada, con un flotador atado. No se hunde, que es más de lo que pueden decir casi todos los libros."
	L["binding.netcork.name"] = "Red sobre corcho"
	L["binding.oilskin.description"] = "Tela amarilla encerada que repele la lluvia y la espuma. Se encuentra a la primera en el fondo de la barca, que es de lo que se trata."
	L["binding.oilskin.name"] = "Hule amarillo"
	L["binding.pearl.description"] = "Una tapa de concha, cortada pieza a pieza y encajada como azulejos. Cambia de color cada vez que se gira el libro."
	L["binding.pearl.name"] = "Nácar"
	L["binding.planks.description"] = "Tablillas finas sujetas con correas de cuero y hebillas de latón. En un apuro, sirve de tabla de cortar."
	L["binding.planks.name"] = "Tablillas atadas"
	L["binding.sailcloth.description"] = "Vela vieja, alquitranada de negro contra el mal tiempo y rematada en los bordes con bramante."
	L["binding.sailcloth.name"] = "Lona de vela alquitranada"
	L["binding.scrimshaw.description"] = "Un viejo panel de marfil rayado con un barco y un pez por algún marinero con un largo viaje y un cuchillo afilado."
	L["binding.scrimshaw.name"] = "Panel grabado en marfil"
	L["binding.shagreen.description"] = "Piel de raya, granulada como la escarcha, con la estrella pálida en el centro que los artesanos de antes siempre conservaban."
	L["binding.shagreen.name"] = "Chagrén de raya"
	L["binding.shagreenbone.description"] = "Piel de raya verde, grano a grano, con hueso incrustado como un amanecer. Hecho para un capitán al que le gustaba que sus libros hicieran juego con el salón."
	L["binding.shagreenbone.name"] = "Chagrén y hueso"
	L["binding.sharkskin.description"] = "Piel gris y áspera con repujado de plata. No se escurre de una mano mojada."
	L["binding.sharkskin.name"] = "Piel de tiburón"
	L["binding.snakeskin.description"] = "La piel de una larga serpiente del pantano, aún con los rombos con los que cazaba. Fría al tacto, siempre."
	L["binding.snakeskin.name"] = "Piel de serpiente"
	L["binding.tartan.description"] = "Lana gruesa verde y azul marino cruzada por una línea roja. Manos calientes, páginas húmedas, ningún remordimiento."
	L["binding.tartan.name"] = "Lana de tartán"
	L["binding.tooled.description"] = "Cuero oscuro repujado con juncos y peces saltando, obra de alguien con un cuchillo afilado y un invierno largo."
	L["binding.tooled.name"] = "Cuero repujado"
	L["binding.trophycase.description"] = "Una vitrina de madera oscura con frente de cristal y, tras el cristal, un pez fundido en oro. Se abre como un armario."
	L["binding.trophycase.name"] = "Vitrina de trofeo dorada"
	L["binding.turtle.description"] = "Placas de caparazón pulidas, ámbar y humo, engastadas en un marco oscuro. Más viejo que el libro, y probablemente le sobrevivirá."
	L["binding.turtle.name"] = "Caparazón de tortuga"
	L["binding.velvet.description"] = "Terciopelo de medianoche bordado con estrellas de plata y una luna. Mejor leído a la luz del farol, que es cuando se lee."
	L["binding.velvet.name"] = "Terciopelo nocturno"
	L["binding.verdigris.description"] = "Esquinas y cierre de cobre, verdes por el aire del mar. Relució una vez, poco tiempo."
	L["binding.verdigris.name"] = "Cardenillo"
	L["good.core.crate.description"] = "Embalado en los muelles por alguien que nunca dice qué llevan dentro. Casi todos los cofres traen un aspecto que aún no tienes, más raro cuanto más hondo rebuscas. Sobre todo, paja."
	L["good.core.crate.name"] = "Cofre de curiosidades"
	L["good.core.crest.fish.12238.description"] = "Un mero gris y ancho sobre el mar gris que le da nombre, con la boca abierta, como siempre."
	L["good.core.crest.fish.12238.name"] = "Blasón de {fish}"
	L["good.core.crest.fish.13422.description"] = "Una anguila de escamas de piedra enroscada sobre agua azul. Los armeros codician el escudo."
	L["good.core.crest.fish.13422.name"] = "Blasón de {fish}"
	L["good.core.crest.fish.13754.description"] = "Un pez azul y pesado en mar abierto, hecho como un puño."
	L["good.core.crest.fish.13754.name"] = "Blasón de {fish}"
	L["good.core.crest.fish.13755.description"] = "Un calamar pálido sobre azul hielo de invierno, por fin con todos los brazos desenredados."
	L["good.core.crest.fish.13755.name"] = "Blasón de {fish}"
	L["good.core.crest.fish.13756.description"] = "Una lubina sobre verde lago, con la boca abierta para toda la temporada."
	L["good.core.crest.fish.13756.name"] = "Blasón de {fish}"
	L["good.core.crest.fish.13757.description"] = "Una anguila sobre un campo de tormenta, aún con chispas en los bordes."
	L["good.core.crest.fish.13757.name"] = "Blasón de {fish}"
	L["good.core.crest.fish.13758.description"] = "Una perca listada sobre un campo rojo brasa. Las agallas son lo más brillante que tiene."
	L["good.core.crest.fish.13758.name"] = "Blasón de {fish}"
	L["good.core.crest.fish.13759.description"] = "Un pargo violeta sobre agua nocturna. Ganado a oscuras, casi siempre."
	L["good.core.crest.fish.13759.name"] = "Blasón de {fish}"
	L["good.core.crest.fish.13760.description"] = "Un salmón de motas doradas que asciende por agua verde, atrapando cada hora de luz."
	L["good.core.crest.fish.13760.name"] = "Blasón de {fish}"
	L["good.core.crest.fish.13888.description"] = "Una langosta sobre azul, pinzas por delante, como ella exige."
	L["good.core.crest.fish.13888.name"] = "Blasón de {fish}"
	L["good.core.crest.fish.13889.description"] = "Un salmón pálido como la escarcha sobre azul frío. Todos sus colores, pescados antes de que se derritiera."
	L["good.core.crest.fish.13889.name"] = "Blasón de {fish}"
	L["good.core.crest.fish.13890.description"] = "Un pez de placas óseas sobre azul hielo, con su armadura por fin superada."
	L["good.core.crest.fish.13890.name"] = "Blasón de {fish}"
	L["good.core.crest.fish.13893.description"] = "El primo grande sobre un campo de mar profundo. Hicieron falta las dos manos, y un amigo, muchas veces."
	L["good.core.crest.fish.13893.name"] = "Blasón de {fish}"
	L["good.core.crest.fish.1467.description"] = "Un pez sol sobre campo verde lago. Para el pescador que lo ha visto con todas las manchas que puede lucir."
	L["good.core.crest.fish.1467.name"] = "Blasón de {fish}"
	L["good.core.crest.fish.16967.description"] = "Un atún de aleta amarilla sobre verde río, con las aletas largas echadas atrás como estandartes."
	L["good.core.crest.fish.16967.name"] = "Blasón de {fish}"
	L["good.core.crest.fish.16968.description"] = "Un cazador listado que cruza agua azul, dientes por delante."
	L["good.core.crest.fish.16968.name"] = "Blasón de {fish}"
	L["good.core.crest.fish.16969.description"] = "Un pez vela sobre el verde azulado de la costa selvática, con la vela izada para el público."
	L["good.core.crest.fish.16969.name"] = "Blasón de {fish}"
	L["good.core.crest.fish.16970.description"] = "Un mahi verde y dorado en la costa selvática, brillante como el día en que lo sacaron."
	L["good.core.crest.fish.16970.name"] = "Blasón de {fish}"
	L["good.core.crest.fish.19807.description"] = "Un pez pecoso en la costa del concurso. Todas sus clases, todos los concursos."
	L["good.core.crest.fish.19807.name"] = "Blasón de {fish}"
	L["good.core.crest.fish.19975.description"] = "Un pez rechoncho y pardo sobre agua turbia. El escudo, por suerte, no huele."
	L["good.core.crest.fish.19975.name"] = "Blasón de {fish}"
	L["good.core.crest.fish.21071.description"] = "Un pez pequeño con su alta aleta alzada, sobre verde de arroyo de ladera."
	L["good.core.crest.fish.21071.name"] = "Blasón de {fish}"
	L["good.core.crest.fish.21153.description"] = "El anciano de su linaje, viejo y señorial, con la aleta como estandarte sobre agua verde."
	L["good.core.crest.fish.21153.name"] = "Blasón de {fish}"
	L["good.core.crest.fish.251524.description"] = "Un pez dorado con una estela de seda azul sobre agua verde. Sigue sin saberse cómo llegó aquí."
	L["good.core.crest.fish.251524.name"] = "Blasón de {fish}"
	L["good.core.crest.fish.4603.description"] = "Un pez de cola amarilla que asciende por agua azul, con la cola por delante en todos los sentidos."
	L["good.core.crest.fish.4603.name"] = "Blasón de {fish}"
	L["good.core.crest.fish.6289.description"] = "Un pargo todo mandíbula, sobre verde charca. Ganado mordisco a mordisco."
	L["good.core.crest.fish.6289.name"] = "Blasón de {fish}"
	L["good.core.crest.fish.6291.description"] = "El pez más pequeño de cualquier escudo, y el más difícil de dejar de pescar."
	L["good.core.crest.fish.6291.name"] = "Blasón de {fish}"
	L["good.core.crest.fish.6299.description"] = "Un triste pez gris sobre agua oscura. Alguien tenía que reunirlos todos. Fuiste tú."
	L["good.core.crest.fish.6299.name"] = "Blasón de {fish}"
	L["good.core.crest.fish.6303.description"] = "Una caballa listada en mar abierto, escurriéndose del marco, como siempre."
	L["good.core.crest.fish.6303.name"] = "Blasón de {fish}"
	L["good.core.crest.fish.6308.description"] = "Bigotes, rencor y verde río. Todos y cada uno se han enfurruñado en tu sedal."
	L["good.core.crest.fish.6308.name"] = "Blasón de {fish}"
	L["good.core.crest.fish.6317.description"] = "Dientes sobre un campo de agua de lago. Los enanos lo aprobarían, y luego se contarían los dedos."
	L["good.core.crest.fish.6317.name"] = "Blasón de {fish}"
	L["good.core.crest.fish.6358.description"] = "Un salmón aceitoso sobre azul, reluciente. Todos los colores que el aceite podía dar, anotados."
	L["good.core.crest.fish.6358.name"] = "Blasón de {fish}"
	L["good.core.crest.fish.6359.description"] = "Un pargo rojo que asciende por agua cálida, para el pescador que lo ha visto en todos los colores que tiene."
	L["good.core.crest.fish.6359.name"] = "Blasón de {fish}"
	L["good.core.crest.fish.6361.description"] = "Un atún blanco con sus aletas de arcoíris bien abiertas, colores que en un escudo nunca se apagan."
	L["good.core.crest.fish.6361.name"] = "Blasón de {fish}"
	L["good.core.crest.fish.6362.description"] = "Un bacalao moteado sobre azul profundo, terco como las rocas entre las que se esconde."
	L["good.core.crest.fish.6362.name"] = "Blasón de {fish}"
	L["good.core.crest.fish.6458.description"] = "Un pez pequeño sobre agua turbia, tan limpio como jamás llegará a estar."
	L["good.core.crest.fish.6458.name"] = "Blasón de {fish}"
	L["good.core.crest.fish.6522.description"] = "Algo con demasiados ojos sobre un campo de agua mala. Señal de un estómago de hierro."
	L["good.core.crest.fish.6522.name"] = "Blasón de {fish}"
	L["good.core.crest.fish.8365.description"] = "Una trucha de cabeza reluciente, sobre verde río. El herrero ha dejado de preguntar."
	L["good.core.crest.fish.8365.name"] = "Blasón de {fish}"
	L["good.core.crest.plain.description"] = "Sin emblema, solo el nombre del dueño. Muchos buenos pescadores nunca quisieron más."
	L["good.core.crest.plain.name"] = "Sencillo"
	L["good.core.newssign.astro.description"] = "Cae una estrella, y un astrolabio de latón gira a su alrededor hasta que su placa se abre al cielo nocturno. La noticia se lee mejor a la luz de las estrellas."
	L["good.core.newssign.astro.name"] = "Astrolabio"
	L["good.core.newssign.coral.description"] = "Cae una gota, y del chapoteo emerge una placa ribeteada de perlas, con algas y coral creciendo alrededor. Suben burbujas. Alguien lee desde allá abajo."
	L["good.core.newssign.coral.name"] = "Coral"
	L["good.core.newssign.kraken.description"] = "Dos tentáculos bajan una tablilla de piedra cubierta de algas, agarrada por las esquinas. Gotea. Sus ventosas laten. Nadie pregunta dónde está el resto."
	L["good.core.newssign.kraken.name"] = "Kraken"
	L["good.core.newssign.lantern.description"] = "Un farol de latón que baja de una cadena ante un cristal oscuro. Se enciende, las líneas aparecen una a una y las luciérnagas se quedan."
	L["good.core.newssign.lantern.name"] = "Farol"
	L["good.core.newssign.scroll.description"] = "Una carta enrollada que baja tras un corcho rojo y blanco. Se desenrolla con la noticia y se lleva un sello de lacre, por si acaso."
	L["good.core.newssign.scroll.name"] = "Pergamino"
	L["good.core.newssign.wood.description"] = "Tablones curtidos colgados de dos cuerdas. Cae, se balancea, se asienta y dice lo suyo. Sencillo, y a mucha honra."
	L["good.core.newssign.wood.name"] = "Madera"
	L["good.core.soundset.arcade.description"] = "Pitidos de moneda y la musiquilla de subir de nivel desde la máquina del fondo de la taberna. Inserta un pez para continuar."
	L["good.core.soundset.arcade.name"] = "Máquina recreativa"
	L["good.core.soundset.boing.description"] = "Un muelle, un cachete y un chapoteo, en el orden que decida el pez. Nadie sale herido."
	L["good.core.soundset.boing.name"] = "¡Boing!"
	L["good.core.soundset.bubbleworks.description"] = "Grandes burbujas redondas que suben del fondo y, a lo lejos, una ballena muy simpática que saluda."
	L["good.core.soundset.bubbleworks.name"] = "Burbujería"
	L["good.core.soundset.dragonroost.description"] = "Un dragón en una cornisa alta, batiendo las alas, y un cuerno que responde a su rugido. Por ese pez valía la pena despertarlo."
	L["good.core.soundset.dragonroost.name"] = "Nido del dragón"
	L["good.core.soundset.driftwood.description"] = "Golpes suaves de madera, como un casco que tropieza con el embarcadero."
	L["good.core.soundset.driftwood.name"] = "Madera a la deriva"
	L["good.core.soundset.dulcimer.description"] = "Un dulcémele de macillos en el rincón de una taberna del puerto, tocado rápido y brillante."
	L["good.core.soundset.dulcimer.name"] = "Dulcémele de taberna"
	L["good.core.soundset.frost.description"] = "Carámbanos que tintinean entre sí con un viento frío y siguen sonando mucho después de quedarse quietos."
	L["good.core.soundset.frost.name"] = "Carillón de escarcha"
	L["good.core.soundset.gilded.description"] = "Cascabeles pequeños y brillantes. Algo pomposos para una caballa, y no por ello peores."
	L["good.core.soundset.gilded.name"] = "Áureo"
	L["good.core.soundset.gizmo.description"] = "Tictac de engranajes, un muelle que se suelta y dos pitidos alegres. Casi seguro que funciona."
	L["good.core.soundset.gizmo.name"] = "Cachivache gnómico"
	L["good.core.soundset.glass.description"] = "Boyas de vidrio verde que chocan entre sí en una red, con burbujas subiendo a su lado."
	L["good.core.soundset.glass.name"] = "Boyas de vidrio"
	L["good.core.soundset.goblintill.description"] = "La caja registradora de un goblin saltando como un premio gordo, monedas por todas partes y el dueño riéndose. No se admiten devoluciones."
	L["good.core.soundset.goblintill.name"] = "Caja goblin"
	L["good.core.soundset.harp.description"] = "Un arpa en un claro del bosque, un breve barrido de cuerdas y las hojas que responden."
	L["good.core.soundset.harp.name"] = "Arpa del claro"
	L["good.core.soundset.kalimba.description"] = "Un piano de pulgar junto al agua que corre, dos notas y un leve zumbido, como si las pulsara el arroyo."
	L["good.core.soundset.kalimba.name"] = "Kalimba del arroyo"
	L["good.core.soundset.kazoo.description"] = "Un kazoo, un silbato de émbolo y un matasuegras desfilando por el puerto como si fuera fiesta. Ahora lo es."
	L["good.core.soundset.kazoo.name"] = "Desfile de kazoos"
	L["good.core.soundset.laser.description"] = "Un artilugio gnomo que chisporrotea, tiembla y zumba, y remata con un alegre tilín. No es un arma, probablemente."
	L["good.core.soundset.laser.name"] = "Láser gnómico"
	L["good.core.soundset.marimba.description"] = "Teclas cálidas de madera, recorridas escala arriba como una ola que llega."
	L["good.core.soundset.marimba.name"] = "Marimba de la orilla"
	L["good.core.soundset.mrglglgl.description"] = "Un múrloc ha visto tu presa y tiene opiniones al respecto. ¡Mrgl! ¡Mrglglgl!"
	L["good.core.soundset.mrglglgl.name"] = "Mrglglgl"
	L["good.core.soundset.musicbox.description"] = "Una melodía diminuta de cuerda, de una caja con un pez pintado en la tapa. Dos vueltas a la llave, ni una más."
	L["good.core.soundset.musicbox.name"] = "Caja de música"
	L["good.core.soundset.parrot.description"] = "Un loro del muelle, un cañón de barco y una campana. El loro anuncia, los piratas lo celebran."
	L["good.core.soundset.parrot.name"] = "Loro pirata"
	L["good.core.soundset.rain.description"] = "Gotas que caen sobre el agua quieta, una tras otra, y detrás el leve rumor de la lluvia."
	L["good.core.soundset.rain.name"] = "Lluvia en el lago"
	L["good.core.soundset.shipbell.description"] = "La campana de latón del mástil, tocada por la captura, con la cuerda y las cuadernas crujiendo debajo."
	L["good.core.soundset.shipbell.name"] = "Esquila de barco"
	L["good.core.soundset.silithid.description"] = "Un enjambre de avispas silítidas pasa zumbando junto a tu captura, entre chasquidos y chillidos. Las manos dentro de la barca."
	L["good.core.soundset.silithid.name"] = "Enjambre silítido"
	L["good.core.soundset.slime.description"] = "Algo verde y tembloroso está encantado con tu pesca y da su aprobación con un chof viscoso."
	L["good.core.soundset.slime.name"] = "La hora de la baba"
	L["good.core.soundset.squeaky.description"] = "Un pato de goma con opiniones firmes sobre tu pieza. Dos chillidos, un chapoteo, ningún remordimiento."
	L["good.core.soundset.squeaky.name"] = "Chillón"
	L["good.core.soundset.steelpan.description"] = "Tambores de acero brillantes de una laguna cálida, dos notas que suenan a que la marea está de tu parte."
	L["good.core.soundset.steelpan.name"] = "Laguna de tambor de acero"
	L["good.core.soundset.succubus.description"] = "Una súcubo en las vigas, ronroneando y carcajeándose de tu pieza. No se lo cuentes a nadie."
	L["good.core.soundset.succubus.name"] = "Susurro de súcubo"
	L["good.core.soundset.wardrums.description"] = "Tambores graves y un cuerno hondo desde las colinas: una captura anunciada como el inicio de una marcha."
	L["good.core.soundset.wardrums.name"] = "Tambores de guerra"
	L["good.core.toaststyle.arcane.description"] = "Inscrito en una ciudad flotante de torres violetas, por un mago que quería saber si se podía invocar un pez. Se podía. No le hizo ninguna gracia."
	L["good.core.toaststyle.arcane.name"] = "Sello arcano"
	L["good.core.toaststyle.birch.description"] = "Escrito en una tira de corteza pelada y atado con bramante. La tinta cala y se queda."
	L["good.core.toaststyle.birch.name"] = "Rollo de abedul"
	L["good.core.toaststyle.bottle.description"] = "Enrollada, tapada con corcho y entregada a la marea. Volvió con mejor pesca que la que llevaba al irse."
	L["good.core.toaststyle.bottle.name"] = "Botella de vidrio marino"
	L["good.core.toaststyle.chart.description"] = "Arrancada de una carta que nadie debió vender. Sondas, líneas de rumbo y una rosa de los vientos que aún apunta al norte."
	L["good.core.toaststyle.chart.name"] = "Carta náutica"
	L["good.core.toaststyle.foil.description"] = "La rara, sacada del sobre al primer intento. Ponla a contraluz y todo el lago corre por ella."
	L["good.core.toaststyle.foil.name"] = "Lámina brillante"
	L["good.core.toaststyle.folio.description"] = "Pan de oro, lapislázuli y bermellón sobre vitela, obra de un escriba con demasiado tiempo y muy pocos peces."
	L["good.core.toaststyle.folio.name"] = "Folio iluminado"
	L["good.core.toaststyle.frost.description"] = "Pasó la noche fuera, sobre el hielo. La escarcha entró por las esquinas con la tinta aún fresca."
	L["good.core.toaststyle.frost.name"] = "Escarchado"
	L["good.core.toaststyle.glacier.description"] = "Tallado del corazón azul de un glaciar más viejo que la primera barca, donde el frío lo atraviesa todo y la luz sale cambiada por el otro lado."
	L["good.core.toaststyle.glacier.name"] = "Corazón de glaciar"
	L["good.core.toaststyle.goblin.description"] = "Impreso en un teletipo que nunca para. Los remaches sostienen el conjunto. Nadie sabe qué hace el engranaje."
	L["good.core.toaststyle.goblin.name"] = "Teletipo goblin"
	L["good.core.toaststyle.hive.description"] = "Mudada por algo grande que vive bajo las dunas y sube cuando la arena canta. Las placas aún zumban; los ojos aún vigilan."
	L["good.core.toaststyle.hive.name"] = "Quitina de colmena"
	L["good.core.toaststyle.kelp.description"] = "Un lomo envuelto en algas y tachonado de perlas, con la página brillando como el interior de una concha."
	L["good.core.toaststyle.kelp.name"] = "Algas y perlas"
	L["good.core.toaststyle.lanternglow.description"] = "Una lámpara cálida que brilla tras cada pieza, para pescadores que siguen fuera después de anochecer."
	L["good.core.toaststyle.lanternglow.name"] = "Luz de farol"
	L["good.core.toaststyle.leaf.description"] = "Una gran hoja, prensada entre dos libros pesados y secada hasta dorarse. Las nervaduras hacen de pauta."
	L["good.core.toaststyle.leaf.name"] = "Hoja prensada"
	L["good.core.toaststyle.magma.description"] = "Sacado de un río de roca fundida por alguien que olvidó traer sartén. La costra se enfría; la pieza no. No tocar."
	L["good.core.toaststyle.magma.name"] = "Flujo de magma"
	L["good.core.toaststyle.moon.description"] = "Vitela azul noche escrita en plata, para la pesca que llega pasada la hora de los faroles."
	L["good.core.toaststyle.moon.name"] = "Vitela de luna"
	L["good.core.toaststyle.ooze.description"] = "Algo salió reptando del pantano y decidió que tu pesca era lo mejor que había comido nunca. Aún está digiriendo las espinas."
	L["good.core.toaststyle.ooze.name"] = "Légamo"
	L["good.core.toaststyle.page.description"] = "Una página nueva arrancada del cuaderno de bitácora y sujeta a un lomo de cuero. Remates de latón, tinta roja."
	L["good.core.toaststyle.page.name"] = "Página arrancada"
	L["good.core.toaststyle.pirate.description"] = "Arrancada de la cubierta de un barco que solo izó una bandera. La tripulación se fue hace mucho; el loro recuerda cada pez y te hablará de todos, a gritos."
	L["good.core.toaststyle.pirate.name"] = "Bandera negra"
	L["good.core.toaststyle.ripple.description"] = "Cuero azul y remates de plata, con anillos tenues que se abren por la página como si algo acabara de picar."
	L["good.core.toaststyle.ripple.name"] = "Onda"
	L["good.core.toaststyle.robot.description"] = "Construido para pescar mientras su creador dormía. Nunca ha dormido, nunca ha parpadeado y nunca ha soltado un pez. El ojo rojo significa que está pensando."
	L["good.core.toaststyle.robot.name"] = "Pescador mecánico"
	L["good.core.toaststyle.rune.description"] = "Nada de papel: una placa de bronce, con la pieza grabada a martillo y las runas talladas alrededor para que no mienta."
	L["good.core.toaststyle.rune.name"] = "Placa rúnica"
	L["good.core.toaststyle.ship.description"] = "Una página del cuaderno de bitácora, amarrada a un lomo de lona de vela. Columnas de mareas en azul marino y un ancla en el margen."
	L["good.core.toaststyle.ship.name"] = "Cuaderno de bitácora"
	L["good.core.toaststyle.sonar.description"] = "Construido por un ingeniero que quería ver a los peces antes de que lo vieran a él. Zumba, hace ping y jamás se ha equivocado con un ping."
	L["good.core.toaststyle.sonar.name"] = "Visor de sonar"
	L["good.core.toaststyle.spider.description"] = "Tejida de noche sobre la ventana de la caseta de botes. Lo que cayera en ella fue suyo primero; solo te presta el nombre."
	L["good.core.toaststyle.spider.name"] = "Tela de la viuda"
	L["good.core.toaststyle.storm.description"] = "La pieza que sacaste cuando toda la gente sensata ya se había ido. El gallardete dice temporal; el pescador dice un lance más."
	L["good.core.toaststyle.storm.name"] = "Frente de tormenta"
	L["good.core.toaststyle.tidepool.description"] = "Una página que cayó al agua y volvió a salir. Arena en el pliegue y una concha de recuerdo."
	L["good.core.toaststyle.tidepool.name"] = "Charca de marea"
	L["variety.12238.barred.description"] = "Franjas anchas y oscuras que se desvanecen cuando descansa. Descansa mucho."
	L["variety.12238.barred.name"] = "Con franjas"
	L["variety.12238.bigmouth.description"] = "Una boca capaz de tragarse un farol. Puede que lo hiciera."
	L["variety.12238.bigmouth.name"] = "Bocazas"
	L["variety.12238.brown.description"] = "Pardo, de estuarios fangosos. Da el mismo guiso."
	L["variety.12238.brown.name"] = "Color pardo"
	L["variety.12238.coast-grey.description"] = "Gris moteado de gris más oscuro, ancho como un escudo. Solo se mueve cuando no le queda más remedio."
	L["variety.12238.coast-grey.name"] = "Gris de costa"
	L["variety.12238.moon-pale.description"] = "Gris pálido, como si lo hubiera desteñido la luna. Mejor guiso de lo que parece a primera vista."
	L["variety.12238.moon-pale.name"] = "Luz de luna"
	L["variety.12238.moonkissed.description"] = "Motas pálidas brillan en él como estrellas sobre agua oscura. Se pesca bajo la luna llena, si las historias aciertan."
	L["variety.12238.moonkissed.name"] = "Beso de luna"
	L["variety.12238.mottled.description"] = "Manchones oscuros como rocas bajo agua somera. Se queda quieto y espera."
	L["variety.12238.mottled.name"] = "Motas oscuras"
	L["variety.12238.night-dark.description"] = "Casi negro, de lo más hondo de la bahía. Nadie lo ve hasta que pica."
	L["variety.12238.night-dark.name"] = "Noche cerrada"
	L["variety.12238.rust-spotted.description"] = "Manchas de óxido sobre gris, como un ancla olvidada demasiado tiempo a la intemperie."
	L["variety.12238.rust-spotted.name"] = "Manchas de óxido"
	L["variety.12238.silverscale.description"] = "Plata donde debería ser gris. Los pescadores de costa dicen que da suerte. Los pescadores de costa necesitan suerte."
	L["variety.12238.silverscale.name"] = "Escama de plata"
	L["variety.13422.banded.description"] = "Anillos de piedra oscura a lo largo del cuerpo, como un pilar tallado."
	L["variety.13422.banded.name"] = "Anillos de piedra"
	L["variety.13422.bedrock-ancient.description"] = "Enormes escamas de piedra, agrietadas y con un brillo ámbar en las juntas. Tiene la edad del acantilado del que salió, por lo que parece."
	L["variety.13422.bedrock-ancient.name"] = "Roca madre"
	L["variety.13422.gold-veined.description"] = "El oro recorre el gris como la mena en la roca. Se sabe de joyeros que han llorado."
	L["variety.13422.gold-veined.name"] = "Veta de oro"
	L["variety.13422.greenstone.description"] = "Escamas verde musgo. Parece llevar un siglo en el lecho de un río."
	L["variety.13422.greenstone.name"] = "Piedra verde"
	L["variety.13422.marble.description"] = "Blanco con vetas grises, como el suelo de un templo. Los armeros se pelean por él."
	L["variety.13422.marble.name"] = "Mármol"
	L["variety.13422.moray-spotted.description"] = "Manchas oscuras por todas partes, como la piel de una morena. Igual de contenta de verte."
	L["variety.13422.moray-spotted.name"] = "Piel de morena"
	L["variety.13422.obsidian.description"] = "Escamas negras y vítreas, cada una con su filo. Se coge por la cola, y con cuidado."
	L["variety.13422.obsidian.name"] = "Obsidiana"
	L["variety.13422.pebble-scaled.description"] = "Escamas como piedrecitas grises. Los armeros pagan bien. La anguila no está de acuerdo."
	L["variety.13422.pebble-scaled.name"] = "Escama de guijarro"
	L["variety.13422.sandstone.description"] = "Escamas cálidas color arena, de costas desérticas. Sigue mordiendo."
	L["variety.13422.sandstone.name"] = "Arenisca"
	L["variety.13422.slate.description"] = "Gris azulado, como la pizarra de un tejado. Igual de difícil de cortar."
	L["variety.13422.slate.name"] = "Pizarra"
	L["variety.13754.barred.description"] = "Franjas anchas sobre el lustre, como un pez vestido para la batalla."
	L["variety.13754.barred.name"] = "Con franjas"
	L["variety.13754.bronzeback.description"] = "Lomo de bronce y vientre pálido. Lo bastante pesado para anclar un esquife."
	L["variety.13754.bronzeback.name"] = "Lomo de bronce"
	L["variety.13754.cobalt.description"] = "Azul cobalto intenso con reflejos violeta. Parece una joya. Pesa como un yunque."
	L["variety.13754.cobalt.name"] = "Cobalto"
	L["variety.13754.dappled.description"] = "Manchas de luz en el lomo, como el sol a través de agua somera."
	L["variety.13754.dappled.name"] = "Luz y sombra"
	L["variety.13754.green-glass.description"] = "Verde como una botella al trasluz. Igual de pesado."
	L["variety.13754.green-glass.name"] = "Vidrio verde"
	L["variety.13754.humpbacked.description"] = "Una joroba de músculo detrás de la cabeza. Tira como una mula."
	L["variety.13754.humpbacked.name"] = "Con joroba"
	L["variety.13754.mirror.description"] = "Tan lustroso que el pescador podría peinarse mirándolo. Casi nadie lo hace, después de la pelea."
	L["variety.13754.mirror.name"] = "Espejo"
	L["variety.13754.onyx.description"] = "Lustre negro, como lacado. Se traga la luz, y el anzuelo."
	L["variety.13754.onyx.name"] = "Ónice"
	L["variety.13754.polished.description"] = "Robusto, azul y lustroso como una bota nueva. Tira como algo del doble de su tamaño."
	L["variety.13754.polished.name"] = "Lustre nuevo"
	L["variety.13754.tidemight.description"] = "Líneas de luz marina corren bajo el lustre. Tira como si la propia marea estuviera al otro lado."
	L["variety.13754.tidemight.name"] = "Fuerza de marea"
	L["variety.13755.blueflash.description"] = "Destella en azul si lo tocas. No le hace ninguna gracia que lo toquen."
	L["variety.13755.blueflash.name"] = "Destello azul"
	L["variety.13755.blushing.description"] = "Rojo de arriba abajo, como se ponen los calamares al asustarse. Normalmente, por el pescador."
	L["variety.13755.blushing.name"] = "Sonrojo"
	L["variety.13755.brindled.description"] = "Rayas oscuras a lo largo del manto, como grietas de escarcha en una ventana."
	L["variety.13755.brindled.name"] = "Grietas de escarcha"
	L["variety.13755.crimson.description"] = "Carmesí de punta a punta, del color de una advertencia. Suelta el doble de tinta."
	L["variety.13755.crimson.name"] = "Carmesí"
	L["variety.13755.frost-pink.description"] = "Rosa pálido, salpicado de motas oscuras que van y vienen al respirar. Llega con la escarcha."
	L["variety.13755.frost-pink.name"] = "Rosa escarcha"
	L["variety.13755.frostlight.description"] = "Luce azul pálido en la oscuridad, como la luna sobre nieve recién caída. Solo se ve con el frío más hondo."
	L["variety.13755.frostlight.name"] = "Luz de escarcha"
	L["variety.13755.glassfrost.description"] = "Claro como el hielo, escarchado en los bordes. Se derrite un poco en la mano, o lo parece."
	L["variety.13755.glassfrost.name"] = "Escarcha de cristal"
	L["variety.13755.long-armed.description"] = "Brazos del doble de lo normal. Más que desenredar, cosa que parecía imposible."
	L["variety.13755.long-armed.name"] = "Brazos largos"
	L["variety.13755.milky.description"] = "Blanco y casi transparente. Fácil de perder en el hielo."
	L["variety.13755.milky.name"] = "Blanco leche"
	L["variety.13755.ring-spotted.description"] = "Anillos oscuros en el manto, como una fila de ojos que vigilan."
	L["variety.13755.ring-spotted.name"] = "Anillado"
	L["variety.13756.bronze.description"] = "Bronce con barras tenues, de aguas rocosas. Salta más que los verdes."
	L["variety.13756.bronze.name"] = "Bronce"
	L["variety.13756.bucketmouth.description"] = "Una boca como un cubo. Se traga los señuelos enteros, y a veces algún patito."
	L["variety.13756.bucketmouth.name"] = "Bocacubo"
	L["variety.13756.golden.description"] = "Oro con una franja de bronce. Una tarde de verano hecha pez."
	L["variety.13756.golden.name"] = "Oro"
	L["variety.13756.lateral-lined.description"] = "Verde, con una línea oscura en cada flanco. Acecha bajo cualquier cosa que dé sombra."
	L["variety.13756.lateral-lined.name"] = "Línea lateral"
	L["variety.13756.lily-pad.description"] = "Moteado como un estanque lleno de nenúfares, que es justo donde acecha."
	L["variety.13756.lily-pad.name"] = "Nenúfar"
	L["variety.13756.midsummer.description"] = "Luce en oro cálido, como la tarde más larga del año. Se pesca en lo más alto del verano, y solo entonces."
	L["variety.13756.midsummer.name"] = "Pleno verano"
	L["variety.13756.red-eyed.description"] = "Ojos rojos como un ocaso de verano. Come con más ganas en el calor de la tarde."
	L["variety.13756.red-eyed.name"] = "Ojos rojos"
	L["variety.13756.shadow.description"] = "Verdinegro y difícil de ver. Vive a la sombra, y la prefiere."
	L["variety.13756.shadow.name"] = "Sombra"
	L["variety.13756.sun-bleached.description"] = "Pálido por el agua somera del verano, la franja reducida a un borrón. Tibio al tacto."
	L["variety.13756.sun-bleached.name"] = "Tono desvaído"
	L["variety.13756.tiger.description"] = "Barras oscuras quebradas como rayas de tigre. Pelea como uno, un ratito."
	L["variety.13756.tiger.name"] = "Tigre"
	L["variety.13757.blackout.description"] = "Negra y silenciosa hasta que la tocas. Entonces, nada silenciosa."
	L["variety.13757.blackout.name"] = "Apagón"
	L["variety.13757.bolt-striped.description"] = "Zigzags amarillos por los flancos, como un rayo dibujado por un niño."
	L["variety.13757.bolt-striped.name"] = "Zigzag"
	L["variety.13757.ember-bellied.description"] = "Vientre naranja, como una anguila eléctrica de ríos cálidos. Muerde con chispa."
	L["variety.13757.ember-bellied.name"] = "Vientre de brasa"
	L["variety.13757.long.description"] = "Una aleta que le recorre todo el cuerpo. Ondea como una bandera en un vendaval."
	L["variety.13757.long.name"] = "Aleta larga"
	L["variety.13757.ozone.description"] = "Huele a lluvia después de la tormenta. El aire a su alrededor se vuelve cortante."
	L["variety.13757.ozone.name"] = "Ozono"
	L["variety.13757.slate.description"] = "Gris como nubes de tormenta. Zumba en una nota más grave."
	L["variety.13757.slate.name"] = "Pizarra"
	L["variety.13757.spark-spotted.description"] = "Motas pálidas que chisporrotean cuando se revuelve. Los guantes no sirven de nada."
	L["variety.13757.spark-spotted.name"] = "Motas de chispa"
	L["variety.13757.stormcaller.description"] = "Rayos azules se bifurcan por su cuerpo y bajan al agua. Las nubes se juntan mientras está en el sedal, o lo parece."
	L["variety.13757.stormcaller.name"] = "Llamatormentas"
	L["variety.13757.thunder-dark.description"] = "Verde oliva oscuro, y zumba. Hormiguea. No se lame."
	L["variety.13757.thunder-dark.name"] = "Trueno oscuro"
	L["variety.13757.white-bolt.description"] = "Blanca como un relámpago, y deslumbra un instante cuando se retuerce."
	L["variety.13757.white-bolt.name"] = "Rayo blanco"
	L["variety.13758.cinder.description"] = "Gris ceniza con agallas rojas encendidas, como un carbón sacado de un fuego apagado."
	L["variety.13758.cinder.name"] = "Rescoldo"
	L["variety.13758.ember-gilled.description"] = "Con barras como una perca y agallas rojas como brasas. El aspecto de siempre, y el genio de siempre."
	L["variety.13758.ember-gilled.name"] = "Agallas de brasa"
	L["variety.13758.fel-scarred.description"] = "Un fuego verde corre bajo las escamas, donde debería estar el rojo. Viene de un agua que recuerda una corrupción."
	L["variety.13758.fel-scarred.name"] = "Cicatriz vil"
	L["variety.13758.fire-gilled.description"] = "Las agallas brillan de verdad. Nadie está seguro de que el agua fuera lo bastante fría."
	L["variety.13758.fire-gilled.name"] = "Agallas de fuego"
	L["variety.13758.ghost.description"] = "Pálido, con agallas rosadas y barras tenues. Se nota frío incluso en verano."
	L["variety.13758.ghost.name"] = "Fantasma"
	L["variety.13758.golden.description"] = "Oro con agallas escarlata. Parece salido de la fuente de un señor."
	L["variety.13758.golden.name"] = "Oro"
	L["variety.13758.olive.description"] = "Oliva más oscuro, de ríos invadidos de maleza. Las agallas brillan más por contraste."
	L["variety.13758.olive.name"] = "Oliva"
	L["variety.13758.redfin.description"] = "Aletas tan rojas como las agallas. Todo el pez parece enfadado, porque lo está."
	L["variety.13758.redfin.name"] = "Aleta roja"
	L["variety.13758.spotted.description"] = "Motas en vez de barras. El mismo genio."
	L["variety.13758.spotted.name"] = "Motas"
	L["variety.13758.yellow.description"] = "Amarillo oro con barras oscuras. Luce como un farol en agua verde."
	L["variety.13758.yellow.name"] = "Amarillo"
	L["variety.13759.crescent-marked.description"] = "Una media luna pálida en cada flanco, como si la luna hubiera dejado su huella."
	L["variety.13759.crescent-marked.name"] = "Media luna"
	L["variety.13759.dawn-caught.description"] = "Rosa y oro, pescado cuando acababa la noche. Un pez nocturno que trasnochó demasiado."
	L["variety.13759.dawn-caught.name"] = "Alba"
	L["variety.13759.dusk.description"] = "Lomo violeta, vientre rosado, como el cielo justo después de ponerse el sol."
	L["variety.13759.dusk.name"] = "Anochecer"
	L["variety.13759.eclipse.description"] = "Negro, con las aletas ribeteadas de oro, como el sol cuando se apaga."
	L["variety.13759.eclipse.name"] = "Eclipse"
	L["variety.13759.indigo.description"] = "Índigo profundo. Desaparece en el agua en cuanto se esconde la luna."
	L["variety.13759.indigo.name"] = "Índigo"
	L["variety.13759.moonfin.description"] = "Aletas blanco plata que atrapan la luz de la luna. Los pescadores aprenden a querer la oscuridad."
	L["variety.13759.moonfin.name"] = "Aleta de luna"
	L["variety.13759.owl-eyed.description"] = "Enormes ojos dorados hechos para la oscuridad. Te devuelve la mirada."
	L["variety.13759.owl-eyed.name"] = "Ojos de búho"
	L["variety.13759.star-speckled.description"] = "Motas pálidas por el lomo, como un cielo con unas pocas estrellas."
	L["variety.13759.star-speckled.name"] = "Motas de estrella"
	L["variety.13759.starfeeder.description"] = "Violeta oscuro, con aletas como la noche. Come a la luz de las estrellas."
	L["variety.13759.starfeeder.name"] = "Comeestrellas"
	L["variety.13759.starsong.description"] = "Sus motas brillan como el cielo nocturno y se mueven cuando gira, como estrellas que rotan. En el muelle se hace el silencio."
	L["variety.13759.starsong.name"] = "Canto estelar"
	L["variety.13760.coin-scaled.description"] = "Plateado, con escamas moteadas de oro que destellan como monedas en un arroyo."
	L["variety.13760.coin-scaled.name"] = "Escama de moneda"
	L["variety.13760.copper.description"] = "Cobre bruñido de la cabeza a la cola. Sabe a salmón, parece una tetera."
	L["variety.13760.copper.name"] = "Cobre"
	L["variety.13760.hooknose.description"] = "Una mandíbula ganchuda y fiera de tanto remontar el río. Parece listo para pelearse con un oso."
	L["variety.13760.hooknose.name"] = "Nariz de gancho"
	L["variety.13760.morning.description"] = "Un rubor de melocotón en el vientre, como la primera luz sobre un río."
	L["variety.13760.morning.name"] = "Mañana"
	L["variety.13760.noonday.description"] = "Oro por todo el lomo, como un río a mediodía."
	L["variety.13760.noonday.name"] = "Mediodía"
	L["variety.13760.red-run.description"] = "Rojo para el remonte del desove, con la cabeza verde. En un buen año, el río se tiñe de rojo con ellos."
	L["variety.13760.red-run.name"] = "Remonte rojo"
	L["variety.13760.river-dark.description"] = "Más oscuro, de ríos en sombra. Las motas doradas resaltan."
	L["variety.13760.river-dark.name"] = "Río oscuro"
	L["variety.13760.silverbright.description"] = "Plata brillante, recién llegado del mar. Apenas una mota de oro."
	L["variety.13760.silverbright.name"] = "Plata viva"
	L["variety.13760.sunfire.description"] = "Cada escama encendida en oro como un sol diminuto. Caliente como una piedra de hogar. Cuesta mirarlo de frente."
	L["variety.13760.sunfire.name"] = "Fuego solar"
	L["variety.13760.twilight.description"] = "Violeta y naranja, como la última luz sobre el río. Se ha ido antes de que oscurezca del todo."
	L["variety.13760.twilight.name"] = "Crepúsculo"
	L["variety.13888.abyssal.description"] = "Una luz violeta brilla en las juntas del caparazón. Ha subido de aguas muy hondas, y parece molesta por ello."
	L["variety.13888.abyssal.name"] = "Abisal"
	L["variety.13888.barnacled.description"] = "Percebes por todo el caparazón. Hace mucho que no muda, y no lo lamenta."
	L["variety.13888.barnacled.name"] = "Percebes"
	L["variety.13888.bigclaw.description"] = "Una pinza el doble de grande que la otra. Sabe muy bien cuál usar."
	L["variety.13888.bigclaw.name"] = "Pinza gorda"
	L["variety.13888.blue-black.description"] = "Caparazón negro azulado, algo moteado, pinzas por delante. La que se esconde bajo cada roca de la bahía."
	L["variety.13888.blue-black.name"] = "Negro azulado"
	L["variety.13888.calico.description"] = "Naranja y negra a parches, como una gata carey. Casi nadie se lo cree."
	L["variety.13888.calico.name"] = "Carey"
	L["variety.13888.ghost.description"] = "Blanca como el hueso. Hasta las pinzas son pálidas. El genio, no."
	L["variety.13888.ghost.name"] = "Fantasma"
	L["variety.13888.mud-brown.description"] = "Parda, de los fondos fangosos. Pinza igual de fuerte."
	L["variety.13888.mud-brown.name"] = "Pardo fango"
	L["variety.13888.red-banded.description"] = "Bandas rojas en la cola. Parece medio cocida ya. No lo está."
	L["variety.13888.red-banded.name"] = "Bandas rojas"
	L["variety.13888.sapphire.description"] = "Azul intenso de punta a punta. Una entre muchísimas. Pinza como las demás."
	L["variety.13888.sapphire.name"] = "Zafiro"
	L["variety.13888.sea-green.description"] = "Verdinegra, como una langosta de mares más fríos."
	L["variety.13888.sea-green.name"] = "Verde mar"
	L["variety.13889.ashen.description"] = "Gris ceniza, de aguas cercanas a las tierras infectadas. Dicen que sigue siendo buen bocado."
	L["variety.13889.ashen.name"] = "Ceniza"
	L["variety.13889.crystal.description"] = "Transparente como el hielo en algunas partes. En la sartén parece fuera de lugar."
	L["variety.13889.crystal.name"] = "Cristal"
	L["variety.13889.frost-white.description"] = "Plata pálida, algo moteado, frío al tacto por mucho que lo dejes al sol."
	L["variety.13889.frost-white.name"] = "Blanco escarcha"
	L["variety.13889.hooknose.description"] = "Mandíbula ganchuda y mirada fría. Escarcha en unos bigotes que no tiene."
	L["variety.13889.hooknose.name"] = "Nariz de gancho"
	L["variety.13889.hot-spring.description"] = "De tono más cálido, de aguas donde brotan manantiales. Echa vapor al sacarlo."
	L["variety.13889.hot-spring.name"] = "Fuente termal"
	L["variety.13889.pearl.description"] = "Un brillo nacarado, sin una sola mancha. Parece tallado."
	L["variety.13889.pearl.name"] = "Perla"
	L["variety.13889.silverblue.description"] = "Un reflejo azul en el lomo, de agua de glaciar."
	L["variety.13889.silverblue.name"] = "Plata azul"
	L["variety.13889.snowflake.description"] = "Manchas blancas sobre plata, como nieve sobre un lago helado."
	L["variety.13889.snowflake.name"] = "Copo de nieve"
	L["variety.13889.spawn-blush.description"] = "Un rubor rosado en los flancos para el desove. Raro en agua tan fría."
	L["variety.13889.spawn-blush.name"] = "Rubor de desove"
	L["variety.13889.wintersheen.description"] = "Dibujos de escarcha cubren cada escama y brillan con un azul tenue. Nunca se descongela, ni en la sartén."
	L["variety.13889.wintersheen.name"] = "Fulgor invernal"
	L["variety.13890.ancient-bulwark.description"] = "Placas gruesas como escudos, grabadas con viejas líneas que brillan en oro. Como si alguien lo hubiera forjado hace mucho y lo hubiera echado a nadar."
	L["variety.13890.ancient-bulwark.name"] = "Baluarte antiguo"
	L["variety.13890.battle-scarred.description"] = "Placas abolladas y viejos surcos. Lo que intentó comérselo se rindió."
	L["variety.13890.battle-scarred.name"] = "Veterano"
	L["variety.13890.bony-backed.description"] = "Placas óseas por el lomo, como un esturión. Lleva la armadura por fuera y el genio por dentro."
	L["variety.13890.bony-backed.name"] = "Lomo óseo"
	L["variety.13890.bronze-plated.description"] = "Placas del color del bronce viejo. Parece listo para un desfile."
	L["variety.13890.bronze-plated.name"] = "Placas de bronce"
	L["variety.13890.gilded.description"] = "Placas con borde de oro, como la armadura de gala de un caballero. Y pelea como tal."
	L["variety.13890.gilded.name"] = "Pan de oro"
	L["variety.13890.iron-plated.description"] = "Placas grises como una armadura de hierro. Lleva un cuchillo más pesado."
	L["variety.13890.iron-plated.name"] = "Placas de hierro"
	L["variety.13890.moss-backed.description"] = "Musgo verde en las placas. Lleva un buen rato sin moverse, y de pronto se mueve."
	L["variety.13890.moss-backed.name"] = "Lomo de musgo"
	L["variety.13890.ore-plated.description"] = "Placas de brillo gris verdoso, como la mena más dura de las montañas. El cuchillo se rinde antes."
	L["variety.13890.ore-plated.name"] = "Placas de mena"
	L["variety.13890.ring-plated.description"] = "Placas en anillos ordenados, como una cota de bandas."
	L["variety.13890.ring-plated.name"] = "Placas anilladas"
	L["variety.13890.spiked.description"] = "Cada placa acaba en una púa. Los pescadores sensatos usan la red."
	L["variety.13890.spiked.name"] = "Púas"
	L["variety.13893.abyss-dark.description"] = "Negro azulado, de la fosa más honda de la bahía. Tira como si la fosa lo quisiera de vuelta."
	L["variety.13893.abyss-dark.name"] = "Negro abismo"
	L["variety.13893.barred.description"] = "Anchas barras oscuras por los costados, como las cuadernas del casco de un barco."
	L["variety.13893.barred.name"] = "Barras"
	L["variety.13893.big-blue.description"] = "Enorme, azul y ancho. A dos manos, y seguramente con un amigo."
	L["variety.13893.big-blue.name"] = "Gran azul"
	L["variety.13893.golden.description"] = "Un gigante de oro. Nadie se cree la historia sin el pez delante."
	L["variety.13893.golden.name"] = "Oro"
	L["variety.13893.hump-shouldered.description"] = "Una gran joroba tras la cabeza. Hecho como un pilote del muelle."
	L["variety.13893.hump-shouldered.name"] = "Jorobado"
	L["variety.13893.leviathans-get.description"] = "Líneas luminosas como viejas runas a lo largo de los flancos. Las historias más antiguas de la bahía hablan de algo mayor que esto. Por algo se empieza."
	L["variety.13893.leviathans-get.name"] = "Cría de leviatán"
	L["variety.13893.old-scarback.description"] = "Cicatrices de dientes más grandes de lo que ningún pescador quiere conocer."
	L["variety.13893.old-scarback.name"] = "Viejo lomo marcado"
	L["variety.13893.sea-green.description"] = "Verde como el agua honda. Hacen falta tres para subirlo a la barca."
	L["variety.13893.sea-green.name"] = "Verde mar"
	L["variety.13893.spotted.description"] = "Manchas pálidas sobre un lomo oscuro, como espuma sobre una ola."
	L["variety.13893.spotted.name"] = "Moteado"
	L["variety.13893.storm-grey.description"] = "Gris como la bahía en plena tormenta. Parece que pesa lo mismo."
	L["variety.13893.storm-grey.name"] = "Gris tormenta"
	L["variety.1467.barred.description"] = "Franjas tenues en los flancos, como las llevan los jóvenes. Algunos nunca las dejan atrás."
	L["variety.1467.barred.name"] = "Con franjas"
	L["variety.1467.blue-cheeked.description"] = "Dos líneas azules en cada mejilla, como pintura de guerra para una guerra muy pequeña."
	L["variety.1467.blue-cheeked.name"] = "Mejillas azules"
	L["variety.1467.copper-breasted.description"] = "Un pecho como una tetera bruñida. Los cocineros dudan, brevemente."
	L["variety.1467.copper-breasted.name"] = "Pecho de cobre"
	L["variety.1467.ember-spotted.description"] = "Las manchas se vuelven rojas en los meses cálidos, como si se hubiera sentado demasiado cerca del fuego."
	L["variety.1467.ember-spotted.name"] = "Manchas de brasa"
	L["variety.1467.golden.description"] = "Sin rastro de verde, solo oro. Las garzas lo ven desde la otra orilla del lago."
	L["variety.1467.golden.name"] = "Oro"
	L["variety.1467.midnight.description"] = "Negro como el fango del lago, manchas incluidas. Fácil de pasar por alto, que es justo la idea."
	L["variety.1467.midnight.name"] = "Medianoche"
	L["variety.1467.pale-shallows.description"] = "Desteñido por bajíos templados y tardes largas. Las manchas apenas se molestan."
	L["variety.1467.pale-shallows.name"] = "Bajío pálido"
	L["variety.1467.peppered.description"] = "Manchas molidas hasta quedar en pimienta. El mismo pez, mejor sazonado."
	L["variety.1467.peppered.name"] = "Pimienta molida"
	L["variety.1467.sunburst.description"] = "Rayos naranjas salen del ojo como la mañana sobre agua quieta. Sigue tibio en la mano."
	L["variety.1467.sunburst.name"] = "Rayos de alba"
	L["variety.1467.sunset-breasted.description"] = "Flancos oliva, manchas oscuras y un pecho como el ocaso sobre el lago. El que conoce todo el mundo."
	L["variety.1467.sunset-breasted.name"] = "Pecho de ocaso"
	L["variety.16967.feeding-barred.description"] = "Barras pálidas destellan en sus flancos, como las del atún cuando caza. Pescado a media comida."
	L["variety.16967.feeding-barred.name"] = "Barras de caza"
	L["variety.16967.ghostfin.description"] = "Pálido entero, las aletas casi transparentes. Nada como un reflejo."
	L["variety.16967.ghostfin.name"] = "Aleta fantasma"
	L["variety.16967.gold-belted.description"] = "Una franja de oro del ojo a la cola. Un pez de obsequio con sus mejores galas."
	L["variety.16967.gold-belted.name"] = "Cinturón de oro"
	L["variety.16967.imperial.description"] = "Azul real intenso, con aletas de oro vivo. Parece demasiado fino para ser el obsequio de nadie."
	L["variety.16967.imperial.name"] = "Imperial"
	L["variety.16967.leaf-lit.description"] = "Una luz verde pálida se mueve bajo las escamas como el sol entre las hojas. La vieja magia del bosque está en estas aguas."
	L["variety.16967.leaf-lit.name"] = "Luz de hojas"
	L["variety.16967.mossback.description"] = "Verdinegro por arriba, como si el bosque le hubiera crecido encima. Nada despacio, y luego muy deprisa."
	L["variety.16967.mossback.name"] = "Lomo de musgo"
	L["variety.16967.sickle-fin.description"] = "Aletas largas y curvas como hoces. Hecho para largos viajes río abajo."
	L["variety.16967.sickle-fin.name"] = "Aleta de hoz"
	L["variety.16967.silverflank.description"] = "Plata más brillante por todo el costado. Las aletas amarillas parecen pintadas."
	L["variety.16967.silverflank.name"] = "Flanco de plata"
	L["variety.16967.verdant.description"] = "Un reflejo verde en el lomo, de agua de río bajo los grandes árboles."
	L["variety.16967.verdant.name"] = "Verdor"
	L["variety.16967.yellowfin.description"] = "Lomo azul oscuro, vientre plateado, largas aletas amarillas. El pez por el que el río es famoso."
	L["variety.16967.yellowfin.name"] = "Aleta amarilla"
	L["variety.16968.blackback.description"] = "Negro por arriba, acero por debajo. Ataca desde la oscuridad."
	L["variety.16968.blackback.name"] = "Lomo negro"
	L["variety.16968.bonecutter.description"] = "Dientes como sierras de hueso y un lomo cubierto de viejas marcas. Las historias de la costa seca dicen que sobrevivió a tres cazadores."
	L["variety.16968.bonecutter.name"] = "Cortahuesos"
	L["variety.16968.bronze.description"] = "Con barras de bronce, de agua cálida. El doble de genio."
	L["variety.16968.bronze.name"] = "Bronce"
	L["variety.16968.chevron.description"] = "Uves oscuras por el lomo, como flechas que apuntan a problemas."
	L["variety.16968.chevron.name"] = "Flechas"
	L["variety.16968.ghost.description"] = "Blanco y casi transparente, las barras una sombra de sí mismas. Los dientes son perfectamente sólidos."
	L["variety.16968.ghost.name"] = "Fantasma"
	L["variety.16968.greyback.description"] = "Gris liso por arriba, blanco por debajo. Solo dientes e intención."
	L["variety.16968.greyback.name"] = "Lomo gris"
	L["variety.16968.needlejaw.description"] = "Dientes como una hilera de agujas. Cuenta los dedos después."
	L["variety.16968.needlejaw.name"] = "Boca de agujas"
	L["variety.16968.sandstrand.description"] = "Color arena, de los bajíos de una costa seca. Invisible hasta que ataca."
	L["variety.16968.sandstrand.name"] = "Arenal"
	L["variety.16968.silver-barred.description"] = "Largo, plateado y con barras, con una mandíbula llena de dientes. Hecho para una sola cosa."
	L["variety.16968.silver-barred.name"] = "Barras de plata"
	L["variety.16968.spotted.description"] = "Manchas negras cerca de la cola, como les salen a los grandes. Sigue esperando pelea."
	L["variety.16968.spotted.name"] = "Moteado"
	L["variety.16969.barred.description"] = "Barras azul pálido por los flancos, encendidas en plena pelea. Se ven mejor en el aire, que es donde pasa la pelea."
	L["variety.16969.barred.name"] = "Barras"
	L["variety.16969.jungle-green.description"] = "Verde como la selva tras la costa. Presume igual."
	L["variety.16969.jungle-green.name"] = "Verde selva"
	L["variety.16969.royal.description"] = "Azul real intenso, con la vela moteada de oro. Los pescadores se turnan para sostenerlo."
	L["variety.16969.royal.name"] = "Real"
	L["variety.16969.silver.description"] = "Más plata que azul. La vela sigue igual de viva."
	L["variety.16969.silver.name"] = "Plata"
	L["variety.16969.skyleaper.description"] = "Líneas de luz azul ondulan por la vela cuando salta. Parece quedarse en el aire más de lo que debería ningún pez."
	L["variety.16969.skyleaper.name"] = "Saltacielos"
	L["variety.16969.spotted-sail.description"] = "Lomo azul, vientre plateado, una vela alta salpicada de motas. La despliega en cuanto alguien mira."
	L["variety.16969.spotted-sail.name"] = "Vela moteada"
	L["variety.16969.sunset-sail.description"] = "Una vela naranja, como la costa al atardecer. Salta más que los azules."
	L["variety.16969.sunset-sail.name"] = "Vela de ocaso"
	L["variety.16969.tall-sailed.description"] = "Una vela más alta que el cuerpo del pez. El viento tira de ella en el sedal."
	L["variety.16969.tall-sailed.name"] = "Vela alta"
	L["variety.16969.violet-sail.description"] = "La vela brilla violeta cuando se emociona. Siempre se emociona."
	L["variety.16969.violet-sail.name"] = "Vela violeta"
	L["variety.16969.white-sail.description"] = "Pálido como la lona de un barco. Los marineros juran que anuncia buen tiempo."
	L["variety.16969.white-sail.name"] = "Vela blanca"
	L["variety.16970.barred.description"] = "Barras oscuras destellan en sus costados cuando pica. Está furioso."
	L["variety.16970.barred.name"] = "Barras"
	L["variety.16970.bluefin.description"] = "Azul en el lomo y las aletas. Más sereno. No mucho."
	L["variety.16970.bluefin.name"] = "Aleta azul"
	L["variety.16970.bull-headed.description"] = "Una frente roma y alta, como la de un macho adulto. Embiste la barca."
	L["variety.16970.bull-headed.name"] = "Cabeza de toro"
	L["variety.16970.dorado.description"] = "Verde y oro con motas azules, como un loro que se aficionó a nadar."
	L["variety.16970.dorado.name"] = "Lampuga"
	L["variety.16970.emerald.description"] = "Verde puro, sin nada de oro. Como una gema caída en la ciénaga."
	L["variety.16970.emerald.name"] = "Esmeralda"
	L["variety.16970.fog-pale.description"] = "Pálido, como si la niebla del pantano se le hubiera metido en el color. Pelea como la niebla, y luego como una mula."
	L["variety.16970.fog-pale.name"] = "Pálido de niebla"
	L["variety.16970.gold-flanked.description"] = "Más oro que verde. Se vuelve gris poco después de sacarlo, así que mira rápido."
	L["variety.16970.gold-flanked.name"] = "Flancos de oro"
	L["variety.16970.marsh-lantern.description"] = "Sus motas brillan verde y oro en la niebla, como faroles en un pantano. Los lugareños dicen que extravía a los pescadores."
	L["variety.16970.marsh-lantern.name"] = "Farol de ciénaga"
	L["variety.16970.reed-green.description"] = "Verde apagado, de los juncos entre la niebla. Difícil de ver hasta que salta."
	L["variety.16970.reed-green.name"] = "Verde junco"
	L["variety.16970.sunfire.description"] = "Naranja y oro, como una hoguera en la orilla. El pantano se calla para mirarlo."
	L["variety.16970.sunfire.name"] = "Fuego solar"
	L["variety.19807.big-spotted.description"] = "Manchas como monedas tiradas. Siempre hay alguien que jura que es otro pez."
	L["variety.19807.big-spotted.name"] = "Manchas grandes"
	L["variety.19807.black.description"] = "Negro con pecas blancas, como un cielo nocturno con prisa."
	L["variety.19807.black.name"] = "Negro"
	L["variety.19807.champions.description"] = "Cada peca brilla como una moneda de oro. De esos peces cuya historia se cuenta durante años."
	L["variety.19807.champions.name"] = "De campeón"
	L["variety.19807.contest-speckle.description"] = "Gris plateado y pecoso. Todos los concursantes del muelle lo reconocen a simple vista."
	L["variety.19807.contest-speckle.name"] = "Pecas de concurso"
	L["variety.19807.gilded.description"] = "Oro con pecas pardas. Se forma corro en el muelle."
	L["variety.19807.gilded.name"] = "Pan de oro"
	L["variety.19807.lucky-speckle.description"] = "Una peca con forma de herradura. Se guarda para la suerte, y luego se come."
	L["variety.19807.lucky-speckle.name"] = "Peca de la suerte"
	L["variety.19807.olive.description"] = "Lomo verde, de bajíos con algas. Los concursantes lo agarran igual."
	L["variety.19807.olive.name"] = "Oliva"
	L["variety.19807.pale.description"] = "Blanco con pecas color crema. Hace girar cabezas en cada concurso."
	L["variety.19807.pale.name"] = "Pálido"
	L["variety.19807.red-speckled.description"] = "Pecas rojas. Parece ya sazonado."
	L["variety.19807.red-speckled.name"] = "Pecas rojas"
	L["variety.19807.silver-speckle.description"] = "Plata más brillante, de aguas abiertas. Las mismas pecas."
	L["variety.19807.silver-speckle.name"] = "Pecas de plata"
	L["variety.19975.bloodmud.description"] = "Rojo oscuro, de un barro donde se hacían viejas ofrendas. Mejor no preguntar."
	L["variety.19975.bloodmud.name"] = "Barro de sangre"
	L["variety.19975.idol-touched.description"] = "Venas rojo violeta brillan tenues en su lomo, como la pintura de un viejo ídolo. Hasta las bestias de estas aguas se apartan de él."
	L["variety.19975.idol-touched.name"] = "Tocado por el ídolo"
	L["variety.19975.jungle-mud.description"] = "Pardo verdoso, del barro hondo de la selva. Y huele a él."
	L["variety.19975.jungle-mud.name"] = "Barro de selva"
	L["variety.19975.long-whiskered.description"] = "Barbillas largas que arrastra por el barro. Encuentra cada cebo, y huele cada uno."
	L["variety.19975.long-whiskered.name"] = "Barbas largas"
	L["variety.19975.masked.description"] = "Una banda oscura sobre los ojos, como una máscara tallada. Parece que sabe cosas."
	L["variety.19975.masked.name"] = "Enmascarado"
	L["variety.19975.ochre.description"] = "Amarillo ocre, como la arcilla con que pintan los trols. No huele mejor."
	L["variety.19975.ochre.name"] = "Ocre"
	L["variety.19975.pale.description"] = "Blanco hueso, de agua bajo piedra antigua. El olor sobrevive al color."
	L["variety.19975.pale.name"] = "Pálido"
	L["variety.19975.skunk-striped.description"] = "Una franja pálida de la cabeza a la cola. Una advertencia, y bien justa."
	L["variety.19975.skunk-striped.name"] = "Raya de mofeta"
	L["variety.19975.slimeback.description"] = "Pardo, viscoso y rechoncho. La nariz lo encuentra antes que los ojos."
	L["variety.19975.slimeback.name"] = "Lomo baboso"
	L["variety.19975.spotted.description"] = "Manchas oscuras sobre pardo, como barro salpicado sobre barro."
	L["variety.19975.spotted.name"] = "Moteado"
	L["variety.21071.banded.description"] = "Bandas tenues como hileras en un huerto de hierbas."
	L["variety.21071.banded.name"] = "Bandas"
	L["variety.21071.dark-sage.description"] = "Verde intenso, de arroyos en sombra. Huele más fuerte."
	L["variety.21071.dark-sage.name"] = "Salvia oscura"
	L["variety.21071.frost-sage.description"] = "Pálido, con un borde escarchado en cada escama. Sabe más limpio, no se sabe por qué."
	L["variety.21071.frost-sage.name"] = "Salvia de escarcha"
	L["variety.21071.gold-sage.description"] = "Verde amarillento como la hierba seca del verano. Huele a un día largo y caluroso."
	L["variety.21071.gold-sage.name"] = "Salvia de oro"
	L["variety.21071.hillside.description"] = "Verde salvia y pecoso, como las colinas sobre el arroyo del que salió."
	L["variety.21071.hillside.name"] = "Ladera"
	L["variety.21071.lavender-finned.description"] = "Aletas color lavanda. Y huele, un poco, a lavanda también."
	L["variety.21071.lavender-finned.name"] = "Aleta de lavanda"
	L["variety.21071.mindbright.description"] = "Una luz pálida titila en las líneas de sus escamas. Quienes lo comen dicen que piensan con más claridad. Lo dicen mucho."
	L["variety.21071.mindbright.name"] = "Mente clara"
	L["variety.21071.silver-sage.description"] = "Plateado, como hojas de salvia volteadas por el viento."
	L["variety.21071.silver-sage.name"] = "Salvia plateada"
	L["variety.21071.sweetgrass.description"] = "Verde vivo y de olor dulce. El único pez que alguien ha querido guardar en un cajón con la ropa blanca."
	L["variety.21071.sweetgrass.name"] = "Hierba dulce"
	L["variety.21071.thyme-spotted.description"] = "Motitas moradas como flores de tomillo. Los cocineros dan el visto bueno."
	L["variety.21071.thyme-spotted.name"] = "Motas de tomillo"
	L["variety.21153.ashen.description"] = "Gris como el humo, y huele un poco a incienso. Ya nadie quema salvia cerca del agua."
	L["variety.21153.ashen.name"] = "Ceniza"
	L["variety.21153.banded.description"] = "Bandas anchas como los anillos de un árbol. Los viejos tienen más."
	L["variety.21153.banded.name"] = "Bandas"
	L["variety.21153.bearded.description"] = "Aletas largas y colgantes como la barba de un viejo sabio. Parece más sabio de lo que es."
	L["variety.21153.bearded.name"] = "Barbudo"
	L["variety.21153.bronze.description"] = "Bronce, de ríos oscuros de taninos. Sabe un poco a té."
	L["variety.21153.bronze.name"] = "Bronce"
	L["variety.21153.elder-sage.description"] = "Viejo, enorme, con las escamas surcadas de líneas de oro pálido como las venas de una hoja. Hay lugares que guardan sus cosas más antiguas."
	L["variety.21153.elder-sage.name"] = "Salvia anciana"
	L["variety.21153.full-grown.description"] = "La salvia ha crecido: más grande, más oscura, igual de fragante."
	L["variety.21153.full-grown.name"] = "Adulto"
	L["variety.21153.golden.description"] = "Oro y fragante. Huele a miel sobre piedra caliente."
	L["variety.21153.golden.name"] = "Oro"
	L["variety.21153.moss-green.description"] = "Moteado como musgo sobre piedra vieja. Huele a bosque húmedo."
	L["variety.21153.moss-green.name"] = "Verde musgo"
	L["variety.21153.silver.description"] = "Un gigante de plata entre los suyos. Creció y le salió el brillo."
	L["variety.21153.silver.name"] = "Plata"
	L["variety.21153.violet-finned.description"] = "Aletas moradas, como la salvia en flor. El aroma es más fuerte en primavera."
	L["variety.21153.violet-finned.name"] = "Aleta violeta"
	L["variety.251524.dreamfin.description"] = "Luce en rosa y azul suave, y deja un leve destello en el agua. A los niños pequeños les dicen que concede deseos. Nadie lo comprueba."
	L["variety.251524.dreamfin.name"] = "Aleta de sueño"
	L["variety.251524.frill-finned.description"] = "Aletas como volantes de encaje. Nada fatal, y tan contento."
	L["variety.251524.frill-finned.name"] = "Volantes"
	L["variety.251524.lemon.description"] = "Amarillo limón con lunares azules. Parece muy contento por algo."
	L["variety.251524.lemon.name"] = "Limón"
	L["variety.251524.lilac.description"] = "Lila con rayas crema. Nada en bucles, sin motivo claro."
	L["variety.251524.lilac.name"] = "Lila"
	L["variety.251524.mint.description"] = "Verde menta con lunares rosas. Parece un caramelo de feria."
	L["variety.251524.mint.name"] = "Menta"
	L["variety.251524.murk-touched.description"] = "Morado oscuro, con los lunares apagados. El único de su clase que parece haber tenido un mal día."
	L["variety.251524.murk-touched.name"] = "Penumbra"
	L["variety.251524.polka-dotted.description"] = "Grandes lunares blancos sobre rosa, como un vestido de fiesta. Lo sabe."
	L["variety.251524.polka-dotted.name"] = "Lunares"
	L["variety.251524.rainbow.description"] = "Todos los colores a rayas, como pintado por un niño con la caja entera. Centellea."
	L["variety.251524.rainbow.name"] = "Arcoíris"
	L["variety.251524.swirled.description"] = "Rosa y azul arremolinados como un glaseado. Despierta en los pescadores el hambre equivocada."
	L["variety.251524.swirled.name"] = "Remolino"
	L["variety.251524.whimsical.description"] = "Oro, con aletas azules ondulantes como los pañuelos de una bailarina. Parece pintado por alguien de muy buen humor."
	L["variety.251524.whimsical.name"] = "Capricho"
	L["variety.4603.all-gold.description"] = "Amarillo de la cola a la nariz. Las gaviotas siguen la barca durante leguas."
	L["variety.4603.all-gold.name"] = "Todo oro"
	L["variety.4603.classic.description"] = "Lomo gris azulado, cola amarilla y un puñado de manchas oscuras. Lo que espera cualquier cocinero de costa."
	L["variety.4603.classic.name"] = "De siempre"
	L["variety.4603.dusky.description"] = "Oscuro por el agua profunda, con el amarillo apagado como latón viejo."
	L["variety.4603.dusky.name"] = "Penumbra"
	L["variety.4603.ghost.description"] = "Casi blanco, con un leve rubor amarillo en la cola. Parece bajo el agua incluso fuera de ella."
	L["variety.4603.ghost.name"] = "Fantasma"
	L["variety.4603.gold-striped.description"] = "Una línea amarilla de la nariz a la cola, como si alguien lo hubiera subrayado."
	L["variety.4603.gold-striped.name"] = "Raya dorada"
	L["variety.4603.greenback.description"] = "Más verde en el lomo, de costas con algas. La cola sigue orgullosamente amarilla."
	L["variety.4603.greenback.name"] = "Lomo verde"
	L["variety.4603.leopard.description"] = "Las manchas se volvieron codiciosas y se juntaron. Guapo, a su manera abarrotada."
	L["variety.4603.leopard.name"] = "Leopardo"
	L["variety.4603.silverside.description"] = "Más espejo que pez en los flancos. Manchas, pocas y tímidas."
	L["variety.4603.silverside.name"] = "Costado de plata"
	L["variety.4603.sunset-tailed.description"] = "La cola arde naranja en vez de amarilla. Aún más orgulloso de sí mismo, si cabe."
	L["variety.4603.sunset-tailed.name"] = "Cola de ocaso"
	L["variety.4603.tidecaller.description"] = "Una fina red azul brilla en sus flancos. Los marineros viejos dicen que la marea cambia cuando se saca uno."
	L["variety.4603.tidecaller.name"] = "Llamamareas"
	L["variety.6289.blackjaw.description"] = "La mandíbula, negra como la tinta hasta las agallas. Tiene opiniones y las comparte."
	L["variety.6289.blackjaw.name"] = "Mandíbula negra"
	L["variety.6289.brindle.description"] = "Veteado como el pelaje de un sabueso. Hay pescadores que juran que gruñe."
	L["variety.6289.brindle.name"] = "Pelaje de sabueso"
	L["variety.6289.golden.description"] = "Un pez dorado salido de una charca parda. La charca parece tan sorprendida como cualquiera."
	L["variety.6289.golden.name"] = "Oro"
	L["variety.6289.lantern-eyed.description"] = "Ojos que atrapan la luz como un candil en una ventana. Más fácil de encontrar al anochecer."
	L["variety.6289.lantern-eyed.name"] = "Ojos de farol"
	L["variety.6289.mudbank.description"] = "Pardo arriba, tostado abajo, mandíbula por delante. El que parece tener cada charca del mundo."
	L["variety.6289.mudbank.name"] = "Ribera de fango"
	L["variety.6289.old-bootbiter.description"] = "Cicatrices de anzuelo, una aleta rota y una cara de confianza absoluta. Cada charca guarda uno."
	L["variety.6289.old-bootbiter.name"] = "Viejo muerdebotas"
	L["variety.6289.pale.description"] = "Pálido como la leche, rosado en las aletas. Demasiado bonito para la mandíbula que lleva."
	L["variety.6289.pale.name"] = "Color leche"
	L["variety.6289.red-clay.description"] = "Rojo óxido, de orillas de arcilla roja. Sabe igual, parece más picante."
	L["variety.6289.red-clay.name"] = "Arcilla roja"
	L["variety.6289.reedbed.description"] = "Franjas verdes tenues, de esconderse entre los juncos. Sigue mordiendo primero."
	L["variety.6289.reedbed.name"] = "Carrizal"
	L["variety.6289.speckled.description"] = "Pecoso de arriba abajo, como un jornalero después de la cosecha."
	L["variety.6289.speckled.name"] = "Con pecas"
	L["variety.6291.blue-striped.description"] = "Una raya azul pulcra en cada costado, como si intentara parecer oficial."
	L["variety.6291.blue-striped.name"] = "Raya azul"
	L["variety.6291.dotted.description"] = "Una fila de puntitos a lo largo del flanco, pulcra como una costura."
	L["variety.6291.dotted.name"] = "Puntos en fila"
	L["variety.6291.glass.description"] = "Se le ve el espinazo. Seguramente él también ve el tuyo."
	L["variety.6291.glass.name"] = "Cristal"
	L["variety.6291.golden.description"] = "Una moneda de oro con aletas. Los niños se lo quieren quedar. Los pescadores también."
	L["variety.6291.golden.name"] = "Oro"
	L["variety.6291.greenback.description"] = "Verde en el lomo, de aguas someras con algas. El doble de difícil de ver."
	L["variety.6291.greenback.name"] = "Lomo verde"
	L["variety.6291.inkfin.description"] = "Oscuro como la punta de una pluma. Nada con los brillantes y no engaña a nadie."
	L["variety.6291.inkfin.name"] = "Aleta de tinta"
	L["variety.6291.rainbow.description"] = "Suelta colores como una pompa de jabón al girarse. Gris en cuanto sale del agua."
	L["variety.6291.rainbow.name"] = "Arcoíris"
	L["variety.6291.redfin.description"] = "Aletas mojadas en rojo. Presume en el banco, rara vez solo."
	L["variety.6291.redfin.name"] = "Aleta roja"
	L["variety.6291.silver.description"] = "Plata sin más, destellando por cientos en los bajíos. El primer pez de muchísimos cuadernos."
	L["variety.6291.silver.name"] = "Plata"
	L["variety.6291.starlit.description"] = "Diminutas motas pálidas brillan en su lomo como una noche despejada. Notable, para algo tan pequeño."
	L["variety.6291.starlit.name"] = "Luz de estrellas"
	L["variety.6299.ashen.description"] = "Gris hasta el hueso, como si hubiera nadado entre ceniza. Hasta las moscas guardan las distancias."
	L["variety.6299.ashen.name"] = "Color ceniza"
	L["variety.6299.bilious.description"] = "Verde amarillento, como una mala mañana. Manipular con guantes."
	L["variety.6299.bilious.name"] = "Color bilis"
	L["variety.6299.blighted.description"] = "Unas venas verdes tenues brillan bajo las escamas. Hay aguas que recuerdan lo que se vertió en ellas."
	L["variety.6299.blighted.name"] = "Tocado por la plaga"
	L["variety.6299.blotchy.description"] = "Cubierto de tristes manchas pardas. Nadie pregunta qué las causó."
	L["variety.6299.blotchy.name"] = "Con manchurrones"
	L["variety.6299.bony.description"] = "Más costillas que pez. Hizo lo que pudo."
	L["variety.6299.bony.name"] = "Pura espina"
	L["variety.6299.bruised.description"] = "Morado y azul a parches, como si hubiera perdido una pelea con la corriente."
	L["variety.6299.bruised.name"] = "Lleno de moratones"
	L["variety.6299.greenish.description"] = "Manchas verdes que no deberían estar ahí. El olor llega antes que el pez."
	L["variety.6299.greenish.name"] = "Tirando a verde"
	L["variety.6299.greyish.description"] = "Gris, flácido y vagamente avergonzado. Tiene mala pinta y huele peor."
	L["variety.6299.greyish.name"] = "Tirando a gris"
	L["variety.6299.recovered.description"] = "Más sano que los demás. Aun así, sin duda uno de ellos, no se sabe cómo."
	L["variety.6299.recovered.name"] = "Convaleciente"
	L["variety.6299.wheezing.description"] = "Las agallas aletean de un modo que suena casi a suspiro. Lo sabe."
	L["variety.6299.wheezing.name"] = "Con resuello"
	L["variety.6303.blueback.description"] = "Más azul, de mar abierto. Se fríe igual de bien."
	L["variety.6303.blueback.name"] = "Lomo azul"
	L["variety.6303.bronze.description"] = "Bronce en el lomo, como una moneda vieja. Raro en una caballa. Le da igual."
	L["variety.6303.bronze.name"] = "Bronce"
	L["variety.6303.emerald.description"] = "Verde como las algas, con un brillo que se apaga en menos de una hora."
	L["variety.6303.emerald.name"] = "Esmeralda"
	L["variety.6303.golden.description"] = "Franjas de oro sobre oro. Parece caro. Se fríe como una caballa."
	L["variety.6303.golden.name"] = "Oro"
	L["variety.6303.pearl.description"] = "Blanco como una concha, las franjas apenas un fantasma de sí mismas. Precioso, y sigue resbalando."
	L["variety.6303.pearl.name"] = "Perla"
	L["variety.6303.plainback.description"] = "Sin una sola franja. Se escapa de las manos más deprisa sin ellas, al parecer."
	L["variety.6303.plainback.name"] = "Lomo liso"
	L["variety.6303.sea-witch.description"] = "Franjas que brillan verde mar en la oscuridad. Los marineros los devuelven al agua. Luego se arrepienten."
	L["variety.6303.sea-witch.name"] = "Bruja del mar"
	L["variety.6303.shallow-water.description"] = "Más pálido, de bahías arenosas junto a la orilla. Sigue escurriéndose."
	L["variety.6303.shallow-water.name"] = "Agua somera"
	L["variety.6303.spotted.description"] = "Puntos donde deberían ir las franjas. Las caballas no son muy de seguir las normas."
	L["variety.6303.spotted.name"] = "Con lunares"
	L["variety.6303.tiger-backed.description"] = "Franjas oscuras onduladas sobre un lomo verdiazul, como ondas congeladas en su sitio."
	L["variety.6303.tiger-backed.name"] = "Lomo de tigre"
	L["variety.6308.albino.description"] = "Blanco y de ojos rosados. Está claro que nunca ha visto el sol, ni piensa verlo."
	L["variety.6308.albino.name"] = "Albino"
	L["variety.6308.black-barbel.description"] = "Negro tinta del bigote a la cola. Se traga la luz y casi todo el cebo."
	L["variety.6308.black-barbel.name"] = "Barbillón negro"
	L["variety.6308.calico.description"] = "Naranja, blanco y negro a parches, como un gato de granero. Igual de poco impresionado."
	L["variety.6308.calico.name"] = "Tricolor"
	L["variety.6308.long-whiskered.description"] = "Bigotes del doble de lo normal. Aspecto de sabio. No lo es."
	L["variety.6308.long-whiskered.name"] = "Bigotes largos"
	L["variety.6308.marbled.description"] = "Moteado como un lecho de río, que es justo donde pasa el tiempo."
	L["variety.6308.marbled.name"] = "Mármol de río"
	L["variety.6308.mudback.description"] = "Pardo fango arriba, crema abajo, bigotes por todas partes. El siluro que parece tener cada río."
	L["variety.6308.mudback.name"] = "Lomo de fango"
	L["variety.6308.riverbed-king.description"] = "Bigotes gruesos como maromas y una boca como la puerta de una bodega. El río lleva años alimentándolo."
	L["variety.6308.riverbed-king.name"] = "Rey del lecho"
	L["variety.6308.slate.description"] = "Gris azulado como piedra de río. Igual de testarudo."
	L["variety.6308.slate.name"] = "Pizarra"
	L["variety.6308.spotted.description"] = "Manchas oscuras en los flancos, como un siluro en su juventud."
	L["variety.6308.spotted.name"] = "Con manchas"
	L["variety.6308.yellowbelly.description"] = "Una panza amarilla y ni pizca de vergüenza. Pelea igual."
	L["variety.6308.yellowbelly.name"] = "Panza amarilla"
	L["variety.6317.ale-barred.description"] = "Franjas ámbar como una cerveza bien tirada. Los enanos les ponen nombre con cariño."
	L["variety.6317.ale-barred.name"] = "Franjas de cerveza"
	L["variety.6317.blackwater.description"] = "Negro como el fondo de un pozo de mina. Los dientes son blancos."
	L["variety.6317.blackwater.name"] = "Agua negra"
	L["variety.6317.dam-breaker.description"] = "Dientes como cinceles y una quijada llena de astillas viejas. Junto al lago, las historias empiezan y acaban con este."
	L["variety.6317.dam-breaker.name"] = "Rompepresas"
	L["variety.6317.ironjaw.description"] = "Quijada oscura como hierro viejo, y casi igual de dura. Se recomiendan guantes."
	L["variety.6317.ironjaw.name"] = "Quijada de hierro"
	L["variety.6317.peat-stained.description"] = "Pardo por el agua de turba. Sabe un poco a humo."
	L["variety.6317.peat-stained.name"] = "Agua de turba"
	L["variety.6317.redbelly.description"] = "Una panza roja como una fragua. Los dientes, los mismos."
	L["variety.6317.redbelly.name"] = "Panza roja"
	L["variety.6317.ruby.description"] = "Rojo entero, como una gema bajo la lámpara de un minero. Siempre hay alguien que intenta venderlo."
	L["variety.6317.ruby.name"] = "Rubí"
	L["variety.6317.silverflank.description"] = "Flancos de plata viva con un centelleo de escamas. Sigue siendo todo dientes."
	L["variety.6317.silverflank.name"] = "Flanco de plata"
	L["variety.6317.slate-backed.description"] = "Lomo gris, panza roja, dientes. Su nombre viene de cómo se porta cuando lo sujetas."
	L["variety.6317.slate-backed.name"] = "Lomo de pizarra"
	L["variety.6317.snowmelt.description"] = "Pálido, del rincón más frío del lago. Muerde igual de fuerte."
	L["variety.6317.snowmelt.name"] = "Deshielo"
	L["variety.6358.black-gummed.description"] = "Encías negras, lomo moteado, un brillo aceitoso. Los alquimistas quieren el aceite."
	L["variety.6358.black-gummed.name"] = "Encías negras"
	L["variety.6358.bright-silver.description"] = "Recién salido de mar abierto y brillante como una hoja de acero. El aceite está ahí de todos modos."
	L["variety.6358.bright-silver.name"] = "Plata viva"
	L["variety.6358.greenback.description"] = "Más verde por arriba, de costas de algas. Igual de aceitoso."
	L["variety.6358.greenback.name"] = "Lomo verde"
	L["variety.6358.hooknose.description"] = "Mandíbula ganchuda tras remontar para desovar. Siempre parece ofendido."
	L["variety.6358.hooknose.name"] = "Nariz ganchuda"
	L["variety.6358.lampblack.description"] = "Un aceite dorado rezuma por sus escamas y brilla débilmente. Los lampareros pagarían lo que fuera. Suelen hacerlo."
	L["variety.6358.lampblack.name"] = "Negro de humo"
	L["variety.6358.pearl.description"] = "Blanco, con un brillo nacarado de tanto aceite. Más bonito que su fama."
	L["variety.6358.pearl.name"] = "Perla"
	L["variety.6358.rainbow-slicked.description"] = "El aceite muestra todos los colores al sol. Más bonito de lo que merece algo tan grasiento."
	L["variety.6358.rainbow-slicked.name"] = "Película irisada"
	L["variety.6358.redflank.description"] = "Enrojecido en los flancos para el desove. Más aceitoso que nunca."
	L["variety.6358.redflank.name"] = "Flanco rojo"
	L["variety.6358.spotless.description"] = "Ni una sola mancha. El aceite se encarga de la decoración."
	L["variety.6358.spotless.name"] = "Sin manchas"
	L["variety.6358.tar-black.description"] = "Negro de la boca a la cola y resbaladizo como el alquitrán. Deja marca en todo lo que toca."
	L["variety.6358.tar-black.name"] = "Negro alquitrán"
	L["variety.6359.charred.description"] = "Negro como un tronco quemado, con las aletas aún al rojo. Parece cocinado. No lo está."
	L["variety.6359.charred.name"] = "Tizón"
	L["variety.6359.coral.description"] = "Más rosado, de aguas de arrecife. Un poco más fresco en la mano."
	L["variety.6359.coral.name"] = "Coral"
	L["variety.6359.deepwater.description"] = "Carmesí oscuro, del agua profunda. Guarda el calor más tiempo."
	L["variety.6359.deepwater.name"] = "Aguas hondas"
	L["variety.6359.ember-spotted.description"] = "Manchas oscuras como pavesas sobre rojo. Huele un poco a humo al sacarlo."
	L["variety.6359.ember-spotted.name"] = "Manchas de brasa"
	L["variety.6359.flame-finned.description"] = "Cuerpo rojo, aletas como llamas. El color que imagina casi todo pescador al oír el nombre."
	L["variety.6359.flame-finned.name"] = "Aletas de llama"
	L["variety.6359.flame-striped.description"] = "Líneas amarillas le recorren el cuerpo como llamas subiendo por una pared."
	L["variety.6359.flame-striped.name"] = "Rayas de llama"
	L["variety.6359.goldfin.description"] = "Aletas de oro en vez de rojas. Sigue tibio."
	L["variety.6359.goldfin.name"] = "Aleta dorada"
	L["variety.6359.phoenix-fin.description"] = "Las aletas arden doradas y el cuerpo brilla como una fragua. El agua humea a su alrededor al sacarlo."
	L["variety.6359.phoenix-fin.name"] = "Aleta de fénix"
	L["variety.6359.smouldering.description"] = "Oscuro como un fuego tapado, rojo en los bordes. Demasiado caliente para sujetarlo mucho rato."
	L["variety.6359.smouldering.name"] = "Rescoldo"
	L["variety.6359.white-flame.description"] = "Blanco, con aletas del rosa de una brasa viva. El calor es de verdad."
	L["variety.6359.white-flame.name"] = "Llama blanca"
	L["variety.6361.aurora.description"] = "Los colores lo recorren en oleadas, de verde a violeta, y nunca se apagan. Nadie sabe explicar por qué."
	L["variety.6361.aurora.name"] = "Aurora"
	L["variety.6361.barred.description"] = "Franjas pálidas en los flancos, como las que muestra el atún blanco cuando come con ganas."
	L["variety.6361.barred.name"] = "Con franjas"
	L["variety.6361.deep-blue.description"] = "Más oscuro, de muy mar adentro. Las aletas conservan los colores un poco más."
	L["variety.6361.deep-blue.name"] = "Azul profundo"
	L["variety.6361.longfin.description"] = "Aletas pectorales largas como un antebrazo. Nada como si el mar fuera suyo."
	L["variety.6361.longfin.name"] = "Aleta larga"
	L["variety.6361.many-hued.description"] = "Lomo azul acero, vientre plateado, aletas de todos los colores. Se apagan en una hora, así que mira deprisa."
	L["variety.6361.many-hued.name"] = "Mil colores"
	L["variety.6361.prism.description"] = "Blanco como la espuma, cada franja de un color. Los conserva un día entero."
	L["variety.6361.prism.name"] = "Prisma"
	L["variety.6361.silverflank.description"] = "Más plata que azul. El arcoíris vive solo en las aletas."
	L["variety.6361.silverflank.name"] = "Flanco de plata"
	L["variety.6361.stormback.description"] = "Gris como los nubarrones, las aletas apagadas a peltre. Pica mejor justo antes de la lluvia."
	L["variety.6361.stormback.name"] = "Lomo de tormenta"
	L["variety.6361.sunset-finned.description"] = "Aletas naranja y rosa, como el cielo al final de un buen día de pesca."
	L["variety.6361.sunset-finned.name"] = "Aletas de ocaso"
	L["variety.6361.violet.description"] = "Un brillo violeta en el lomo. Los colores se apagan a un gris enfurruñado tras sacarlo."
	L["variety.6361.violet.name"] = "Violeta"
	L["variety.6362.barnacled.description"] = "Percebes en la cabeza, como un casco viejo. Está claro que lleva mucho tiempo en esto."
	L["variety.6362.barnacled.name"] = "Con percebes"
	L["variety.6362.golden.description"] = "Moteado de oro sobre oro. Parece una estatua que alguien olvidó terminar."
	L["variety.6362.golden.name"] = "Oro"
	L["variety.6362.granite.description"] = "Moteado blanco y negro como una piedra de molino. Pesa como si lo fuera."
	L["variety.6362.granite.name"] = "Granito"
	L["variety.6362.harbour-grey.description"] = "Gris por el agua del puerto. Igual de dulce una vez cocinado."
	L["variety.6362.harbour-grey.name"] = "Gris de puerto"
	L["variety.6362.kelp-green.description"] = "Verde pardo, de los bosques de algas. Tira más de lo que aparenta."
	L["variety.6362.kelp-green.name"] = "Verde alga"
	L["variety.6362.leopard.description"] = "Manchas oscuras y marcadas sobre un cuerpo arenoso. Testarudo incluso para un bacalao."
	L["variety.6362.leopard.name"] = "Leopardo"
	L["variety.6362.red-rock.description"] = "Rojo óxido, de costas de roca roja. Los del lugar lo llaman de otra manera. Es el mismo pez."
	L["variety.6362.red-rock.name"] = "Roca roja"
	L["variety.6362.rock-mottled.description"] = "Moteado de pardo como las rocas entre las que se esconde, con una línea pálida en cada flanco."
	L["variety.6362.rock-mottled.name"] = "Piel de roca"
	L["variety.6362.sandy.description"] = "Pálido como una playa, de pecas finas. Luce bien en el plato."
	L["variety.6362.sandy.name"] = "Color arena"
	L["variety.6362.stoneheart.description"] = "Escamas como pizarra, con un leve brillo entre ellas. Se encuentra donde los acantilados dan al agua honda, y en ningún otro sitio."
	L["variety.6362.stoneheart.name"] = "Corazón de piedra"
	L["variety.6458.black-gold.description"] = "Tan recubierto que reluce como una bota lustrada. Los buscadores le echan un vistazo y se ponen a cavar."
	L["variety.6458.black-gold.name"] = "Oro negro"
	L["variety.6458.half-clean.description"] = "El aceite solo pilló la mitad. La otra mitad parece aliviada, en silencio."
	L["variety.6458.half-clean.name"] = "A medio limpiar"
	L["variety.6458.muddy.description"] = "Más barro que aceite. Una mejora, en cierto modo."
	L["variety.6458.muddy.name"] = "Con barro"
	L["variety.6458.rainbow-slick.description"] = "El aceite suelta arcoíris al sol. Bonito de ver, y mala señal."
	L["variety.6458.rainbow-slick.name"] = "Mancha irisada"
	L["variety.6458.rust-streaked.description"] = "Vetas de óxido de viejos vertidos de máquinas. Casi un pez del todo."
	L["variety.6458.rust-streaked.name"] = "Vetas de óxido"
	L["variety.6458.slicked.description"] = "Un pez pequeño bajo un abrigo negro de aceite. En algún sitio río arriba, alguien está muy ocupado."
	L["variety.6458.slicked.name"] = "Capa de aceite"
	L["variety.6458.somehow-clean.description"] = "Limpio, brillante, sano. Tiene que haber llegado nadando de otra parte."
	L["variety.6458.somehow-clean.name"] = "Limpio de milagro"
	L["variety.6458.still-burning.description"] = "El aceite del lomo sigue ardiendo sin llama y nada lo apaga. Mejor no cocinarlo bajo techo."
	L["variety.6458.still-burning.name"] = "Aún ardiendo"
	L["variety.6458.sulphur-stained.description"] = "Amarillo por algo peor que el aceite. Y huele a ello."
	L["variety.6458.sulphur-stained.name"] = "Mancha de azufre"
	L["variety.6458.tarred.description"] = "Alquitrán negro y espeso a parches. Se pega al sedal y al pescador."
	L["variety.6458.tarred.name"] = "Con alquitrán"
	L["variety.6522.crimson.description"] = "Rojo donde debería ser verde. Las historias sobre la hora después de comérselo empeoran."
	L["variety.6522.crimson.name"] = "Carmesí"
	L["variety.6522.dreamers-spawn.description"] = "Una luz verde late bajo sus escamas, lenta como la respiración de quien duerme. La pesadilla de las cavernas dejó aquí su huella."
	L["variety.6522.dreamers-spawn.name"] = "Engendro del soñador"
	L["variety.6522.glowgill.description"] = "Agallas que brillan con un verde tenue. Parece una advertencia, y lo es."
	L["variety.6522.glowgill.name"] = "Agalla luminosa"
	L["variety.6522.lizard-scaled.description"] = "Escamas como el cuero de un raptor. Mitad pez, mitad algo con opiniones."
	L["variety.6522.lizard-scaled.name"] = "Escama de lagarto"
	L["variety.6522.many-eyed.description"] = "Ocelos por todo el flanco. Al menos dos parpadean."
	L["variety.6522.many-eyed.name"] = "Muchos ojos"
	L["variety.6522.misshapen.description"] = "Verde, abultado y mal hecho por varios sitios a la vez. Cómelo bajo tu responsabilidad."
	L["variety.6522.misshapen.name"] = "Deforme"
	L["variety.6522.pale-nightmare.description"] = "Pálido como un fantasma, con las entrañas a la vista. Tiene pinta de mal sueño a mediodía."
	L["variety.6522.pale-nightmare.name"] = "Pesadilla pálida"
	L["variety.6522.purple-finned.description"] = "Aletas color moratón. Nadie se pone de acuerdo en si eso es mejor o peor."
	L["variety.6522.purple-finned.name"] = "Aleta morada"
	L["variety.6522.spined.description"] = "Una cresta de espinas en el lomo que ayer no estaba."
	L["variety.6522.spined.name"] = "Con espinas"
	L["variety.6522.two-tailed.description"] = "Dos colas, y nada como si discutiera consigo mismo cuál usar."
	L["variety.6522.two-tailed.name"] = "Dos colas"
	L["variety.8365.bright-headed.description"] = "Cuerpo oliva, flancos pecosos y una cabeza que brilla como metal bruñido. La trucha de siempre en los ríos templados."
	L["variety.8365.bright-headed.name"] = "Cabeza brillante"
	L["variety.8365.brook-spotted.description"] = "Motas pálidas sobre oliva, de arroyos fríos y rápidos."
	L["variety.8365.brook-spotted.name"] = "Motas de arroyo"
	L["variety.8365.golden.description"] = "Dorado de arriba abajo, como la rara trucha de los lagos altos de montaña."
	L["variety.8365.golden.name"] = "Oro"
	L["variety.8365.goldhead.description"] = "Oro donde el brillo debería ser plata. El herrero pregunta dos veces."
	L["variety.8365.goldhead.name"] = "Cabeza de oro"
	L["variety.8365.ironhead.description"] = "Oscuro entero, con la cabeza como hierro fundido. Igual de difícil de cocinar."
	L["variety.8365.ironhead.name"] = "Cabeza de hierro"
	L["variety.8365.parr-marked.description"] = "Marcas como huellas de pulgar en los flancos, como las de las truchas jóvenes. Madura tarde."
	L["variety.8365.parr-marked.name"] = "Marcas de cría"
	L["variety.8365.quicksilver.description"] = "Plata de la nariz a la cola, con un brillo azul pálido. El herrero por fin tiene algo de razón."
	L["variety.8365.quicksilver.name"] = "Azogue"
	L["variety.8365.rainbow-banded.description"] = "Una banda rosa en el flanco, como la que lleva la trucha arcoíris."
	L["variety.8365.rainbow-banded.name"] = "Banda irisada"
	L["variety.8365.red-spotted.description"] = "Motas rojas con anillo azul. Lo bastante bonito para que un pescador se lo piense antes de la sartén."
	L["variety.8365.red-spotted.name"] = "Motas rojas"
	L["variety.8365.steelhead.description"] = "Gris azulado y brillante, de aguas grandes. Tira como si fuera en serio."
	L["variety.8365.steelhead.name"] = "Cabeza de acero"
end)
